export const PAPER_QUESTIONS: SourceQuestion[] = [
  { id: "pyq-2022-june-pi-01", session: "June 2022", year: 2022, paper: "I", number: 1, marks: 10, kind: "short-note", question: "Describe briefly on Vit.D metabolism, clinical features and management of Vit.D deficiency? [5+3+2]" },
  { id: "pyq-2022-june-pi-02", session: "June 2022", year: 2022, paper: "I", number: 2, marks: 10, kind: "long", question: "A 30-year-old lady came to you with fever of 3 days, decreased food intake and nausea. Clinically jaundice was present. There were similar cases in the family. What is the clinical diagnosis? What are the differential diagnoses? How will you proceed to evaluate? How do you prevent the condition. [2+2+3+3]" },
  { id: "pyq-2022-june-pi-03", session: "June 2022", year: 2022, paper: "I", number: 3, marks: 10, kind: "enumerate", question: "Mention the causes for chronic aches and pains. How do you differentiate that from inflammatory arthritis? How do you evaluate a patient with chronic aches and pains? Describe briefly regarding management of chronic pain? [2+2+2+4]" },
  { id: "pyq-2022-june-pi-04", session: "June 2022", year: 2022, paper: "I", number: 4, marks: 10, kind: "enumerate", question: "Enumerate the causes of falls in the elderly. How would you assess the risks of fall in elderly? How can we prevent falls in elderly? [4+3+3]" },
  { id: "pyq-2022-june-pi-05", session: "June 2022", year: 2022, paper: "I", number: 5, marks: 10, kind: "long", question: "A 45-year-old overweight man came to you with recent onset tiredness, dryness of mouth, weight loss and nocturia. What is your clinical diagnosis? How will you manage him after diagnosis? [10]" },
  { id: "pyq-2022-june-pi-06", session: "June 2022", year: 2022, paper: "I", number: 6, marks: 10, kind: "short-note", question: "Describe the condition and causes of gastroesophageal reflux diseases (GERD), give anatomical basis of GERD? Write briefly on the management of GERD from a family medicine perspective? [4+3+3]" },
  { id: "pyq-2022-june-pi-07", session: "June 2022", year: 2022, paper: "I", number: 7, marks: 10, kind: "enumerate", question: "Enumerate skin, mucosal, and systemic manifestations of protein calorie malnutrition. [4+3+3]" },
  { id: "pyq-2022-june-pi-08", session: "June 2022", year: 2022, paper: "I", number: 8, marks: 10, kind: "enumerate", question: "What is delirium? How is it different from dementia? Enumerate the causes, differential diagnosis and management of delirium? [1+1+3+3+2]" },
  { id: "pyq-2022-june-pi-09", session: "June 2022", year: 2022, paper: "I", number: 9, marks: 10, kind: "short-note", question: "Write briefly on reasons for chemical poisonings. Enumerate clinical features, management, and complications of organophosphorus poisoning? [3+3+2+2]" },
  { id: "pyq-2022-june-pi-10", session: "June 2022", year: 2022, paper: "I", number: 10, marks: 10, kind: "long", question: "A 50 year old male known to have diabetes and hypertension for 15 years. He had history of acute coronary syndrome a year ago. Now comes to you with fatigue, decreased food intake and dyspnea on exertion. Clinically pedal edema, elevated JVP and on bilateral auscultation of the lung bases, he had fine crepitations. What clinical possibilities will you entertain? How do you proceed to evaluate this patient? As a family physician, how will you manage this case? [2+4+4]" },
  { id: "pyq-2022-december-pi-01", session: "December 2022", year: 2022, paper: "I", number: 1, marks: 10, kind: "long", question: "A 38-year-old Mr. Ravi was brought to the casualty with the history of first episode of seizures lasting for one minute. There was up rolling of eyes and drooling of saliva with loss of consciousness, regained consciousness after 2 minutes. There was no post ictal phase. The entire episode lasted for 5 min. Wife of Mr. Ravi gives history of alcohol intake by him of 180ml for past 20 years. His last drink was 3 days back – since he didn’t have work and didn’t have money. His BP is 130/80, PR- 92/min, SpO2- 100 %, GRBS- 110, He is oriented to time, place, person. a) What is your differential diagnosis? [2] b) What is your approach for above mentioned scenario? [5] c) If GRBS- 50mg%. How will you treat immediately? [1] d) How will you manage Alcohol related complications? [2]" },
  { id: "pyq-2022-december-pi-02", session: "December 2022", year: 2022, paper: "I", number: 2, marks: 10, kind: "long", question: "Mrs. Pratibha 73-years-old, staying with her spouse presents to Outpatient department with history of fall 2 days back in her home. Six months ago also, she had a similar complaint and she sustained a Colle’s fracture of the right hand. Her first fall was one year ago when she sustained minor abrasions. a) What is the pathophysiology of Falls? [2] b) What are the risk factors? [2] c) How will you do the OPD assessment of falls? [4] d) How are you going to prevent further falls in Mrs. Pratibha? [2]" },
  { id: "pyq-2022-december-pi-03", session: "December 2022", year: 2022, paper: "I", number: 3, marks: 10, kind: "enumerate", question: "A 23-year-old man was admitted to emergency room of primary care hospital for vomiting and upper abdominal pain. His random blood sugar was found to be 586mg/dl. He is hemodynamically stable. His urine ketones were +++ a) Mention the immediate life-threatening condition this patient can have. [1] b) Mention the investigations you would want to do, substantiate you answer. [3] c) What are the complications of this condition? [2] d) Discuss the management of this condition in detail up to discharge. [4]" },
  { id: "pyq-2022-december-pi-04", session: "December 2022", year: 2022, paper: "I", number: 4, marks: 10, kind: "long", question: "A 67-year-old lady was brought to the emergency room with h/o dizziness but no loss of consciousness. She is a known diabetic and hypertensive, occasionally noncompliant with her medications. Her BP is 130/86mmHg, PR- 86/min - irregularly irregular, GRBS- 186mg%. a) What immediate office investigation would you do? [1] b) What may be the most probable diagnosis? [1] c) What other investigations you would want to do? [2] d) What are the complications of this condition? [2] e) How will you assess this patient for stroke risk? [2] f) How will you manage this patient? [2]" },
  { id: "pyq-2022-december-pi-05", session: "December 2022", year: 2022, paper: "I", number: 5, marks: 10, kind: "long", question: "A 40-year-old lady presented to outpatient department with multiple joint pain, hair loss, oral ulcers, malar rash, breathlessness, and history of passing blood in urine. a) How will you evaluate the history and physical finding to come to a woking diagnosis in an adult patient with multiple inflammatory arthritis? [4] b) What are your differential diagnosis? [2] c) What investigations you would want to do? [2] d) What are the complications of the most probable diagnosis? [2]" },
  { id: "pyq-2022-december-pi-06", session: "December 2022", year: 2022, paper: "I", number: 6, marks: 10, kind: "long", question: "A 48-year-old lady, known case of diabetes, hypertension, dyslipidemia, presented to outpatient department with skin lesions over her elbows, knee, which has increased over past 3 weeks. Earlier she had small lesion for which she used moisturizer which didn’t bother her much. These lesions are well defined, erythematous plaques, with irregular borders and silvery scales. a) What is the most probable final diagnosis? And how will you confirm your diagnosis? [2] b) How will you manage this condition? [4] c) What are the complications of this condition? [3] d) When will you refer this patient to a specialist? [1]" },
  { id: "pyq-2022-december-pi-07", session: "December 2022", year: 2022, paper: "I", number: 7, marks: 10, kind: "long", question: "A 48-year-old Mrs.Lata has been diagnosed with end stage Breast cancer and her oncologist told her that there is no further treatment. She wants to discuss with you about her feelings and about the events which may follow: a) End of life care. [5] b) Advanced directives.in the light of indian laws and guidelines. [5]" },
  { id: "pyq-2022-december-pi-08", session: "December 2022", year: 2022, paper: "I", number: 8, marks: 10, kind: "long", question: "A 42-year-old Ravi was working in fields when he suddenly had snake bite. Before he or his fellow workers could identify, the snake had escaped. a) Which are the common snake bites in India? [1] b) From the clinical features of the patient, how would you identify the type of snake bite? [2] c) What investigations will you do (bed side and Lab)? [2] d) What are the complications of snake bite? [2] e) How will you treat Snake envenomation? [3]" },
  { id: "pyq-2023-april-pi-09", session: "April 2023", year: 2023, paper: "I", number: 9, marks: 10, kind: "long", question: "A 48-year-old Krishnan presented to OPD with history of Abdominal distension over past 3 weeks, gradually increasing, His wife gives history that he was diagnosed as a case of cirrhosis of liver 6 months ago: a) What are the common causes of cirrhosis? [2] b) What are the clinical manifestations - symptoms and signs of cirrhosis? [2] c) What are the complications of cirrhosis? [2] d) How will you manage (INV+Treatment) this patient? [2] e) How will you assess the severity of cirrhosis? [2]" },
  { id: "pyq-2023-april-pi-10", session: "April 2023", year: 2023, paper: "I", number: 10, marks: 10, kind: "enumerate", question: "A 45-year-old woman - P3L3 - is accompanied by her daughter for episodes of fear and palpitations. She is a known hypertensive and is on telmisartan - thiazide 40/12.5mg OD. Since January, following a marital conflict, she has experienced multiple episodes of sudden onset of palpitations, sweating and dizziness. She is fearful of similar recurrence of such episodes. Her multiple visits to hospitals during those episodes showed a BP- 220/120 mmHg with negative cardiology work-up. Her vital signs now - BP- 160/90 mmHg, P-90/min, no elevated JVP or pedal oedema. a) Describe the diagnostic criteria of panic attacks. [3] b) List the possible medical conditions that may mimic a panic attack. [2] c) Describe the options of pharmacotherapy for this patient. [3] d) What are the non-pharmacological treatment options for this patient? [2]" },
  { id: "pyq-2023-april-pi-01", session: "April 2023", year: 2023, paper: "I", number: 1, marks: 10, kind: "long", question: "Mr. A, is a 35 year old asthmatic on inhalers and regular follow up. He had no acute asthma attacks for the last 8 months. He developed sudden onset of breathlessness and was rushed to the hospital. a) How do you clinically assess him for severe asthma? [2] b) How will you manage acute asthma attack? [2] c) How will you prevent asthma exacerbation? [2] d) On examination, patient is found to have trachea deviated to the right side and absent air entry on the left side of the chest. What is the likely diagnosis and what are the other clinical features for this? [2] e) How will you manage this condition? [2]" },
  { id: "pyq-2023-april-pi-02", session: "April 2023", year: 2023, paper: "I", number: 2, marks: 10, kind: "long", question: "Mrs. S had fever for 2 days. 5 days later, she developed severe pain in both the hands, fingers and toes. She has stiffness of hands and fingers in the mornings for about 45 minutes. She consults you after 1 week for her symptoms. a) What diagnosis will you entertain and what treatment will you provide? [2] Patient continues to have symptoms and there is no improvement even after 8 months. During the period, she has loss of hair and mouth ulcers. b) What differential diagnosis will you consider? [2] c) What investigations will you order? [3] d) Patient has been seen by a rheumatologist and started on Prednisolone and Methotrexate. He has asked you to monitor the patient. How will you do it? [3]" },
  { id: "pyq-2023-april-pi-03", session: "April 2023", year: 2023, paper: "I", number: 3, marks: 10, kind: "long", question: "A 45-year-old man who has been drinking 3-4 pegs of whisky for few years, comes with complaints of yellowish discolouration of the eyes and loss of appetite along with abdomen pain. His last drink was 12 hrs ago. The family is worried and asks you to evaluate him and manage. a) What are the possible causes for his jaundice? [1] b) What tool can be used to screen for alcohol abuse? [2] c) What laboratory tests will confirm your diagnosis? [3] d) The patient is not willing to go to the hospital immediately and wants to wait for 2 to 3 days. What treatment will you provide before the patient decides to go to hospital? [2] e) Patient has been discharged from the hospital, how will you prevent a relapse of his alcohol problem? [2]" },
  { id: "pyq-2023-april-pi-04", session: "April 2023", year: 2023, paper: "I", number: 4, marks: 10, kind: "long", question: "A patient who was diagnosed to be infected with HIV, has been started on cotrimoxazole as prophylaxis. Two days later, he develops ulcers in the mouth and diffuse rash all over the body. a) What is the differential diagnosis? [2] b) How will you treat this condition? [5] c) What are the infections he is at risk for? [3]" },
  { id: "pyq-2023-april-pi-05", session: "April 2023", year: 2023, paper: "I", number: 5, marks: 10, kind: "long", question: "Mr. M is an obese individual. He was diagnosed as having diabetes and started on Tab. Glibenclamide 5mg two times a day. Three days after starting the treatment, his wife found that he was unresponsive and called you to see the patient. a) What is the likely diagnosis? [1] b) What treatment will you institute at home? [2] c) He is shifted to your nursing home. What treatment will you provide in the hospital? [3] d) What medication and advice will you provide on discharge? [4]" },
  { id: "pyq-2023-april-pi-06", session: "April 2023", year: 2023, paper: "I", number: 6, marks: 10, kind: "long", question: "A 20-year-old lady presents with fever, headache and vomiting for the past 3 days. a) What is your differential diagnosis? [2] b) What clinical features will you elicit to assess her? [2] c) Outline the investigations and management of bacterial and tuberculous meningitis. [6]" },
  { id: "pyq-2023-april-pi-07", session: "April 2023", year: 2023, paper: "I", number: 7, marks: 10, kind: "long", question: "Mr A. is a 70-year-old man who runs a small store. Recently his family has noticed that he has been very forgetful. His accounts in the shop has been going wrong. He has also started neglecting his personal grooming. At nights he shouts and says that he is seeing relatives who have died and are calling him. Sometimes he is incontinent of urine. a) What is the likely diagnosis? Outline the causes for it. [3] b) Discuss investigations that will help you assess for this conditon. [4] c) Discuss how you will help the patient and the family as their family doctor. [3]" },
  { id: "pyq-2023-april-pi-08", session: "April 2023", year: 2023, paper: "I", number: 8, marks: 10, kind: "enumerate", question: "A 70-year-old lady presents with pain of the left shoulder for the 2 weeks. She is a diabetic and a hypertensive. a) List the differential diagnosis. [2] b) You suspect that she could be having coronary heart disease. How will you investigate to confirm this? [3] c) Outline the management of effort angina and unstable angina. [5]" },
  { id: "pyq-2023-october-pi-01", session: "October 2023", year: 2023, paper: "I", number: 1, marks: 10, kind: "define-classify", question: "Mrs. Shakila, 30-year-old female, works as a clerk in Government office. She presented to your OPD with complaints of recurrent headache for the past 2 years, 3-4 episodes per month, associated with nausea and occasional vomiting, a) What could be the cause of her headache? How do you evaluate her? [3] b) How do you classify headaches? What are the common causes? [3] c) Mention 2 drugs that cause headache. [1] d) What are the red flags in history and physical examination of headaches? [3]" },
  { id: "pyq-2023-october-pi-02", session: "October 2023", year: 2023, paper: "I", number: 2, marks: 10, kind: "enumerate", question: "A 68-year-old male was brought to you with history of sudden onset headache and difficulty in using left upper and lower limbs since past 40 min. He was stuporous and BP- was190//120mmHg, Power in Left UL and LL was 2/5. a) What is your clinical diagnosis in this patient? Mention the causes of cerebrovascular accidents. [2] b) How do you clinically differentiate between thrombotic and hemorrhagic strokes? [3] c) What are the findings on CT for a hemorrhagic stroke? [2] d) What are the indications of thrombolysis and what are the guidelines for administration of r-tPA? [3]" },
  { id: "pyq-2023-october-pi-03", session: "October 2023", year: 2023, paper: "I", number: 3, marks: 10, kind: "long", question: "A 58-years-old female presented to you with history of feeling hopelessness, tiredness for 3 months and has put on 5 kg weight, feels fatigued and drowsy: a) Which are the medical conditions that can mimic depression? [3] b) What are the criteria for a depressive episode? [3] c) What is the tool used as a diagnostic aid in primary care? [2] d) When do you refer a patient of depression to a specialist? [2]" },
  { id: "pyq-2023-october-pi-04", session: "October 2023", year: 2023, paper: "I", number: 4, marks: 10, kind: "long", question: "A 56-year-old male presented to OPD with complaints of swelling of feet and breathing difficulty which has been increasing over the past 8 weeks. He is a diabetic and hypertensive: a) What are the precipitating causes of cardiac failure? [2] b) What are the signs of left and right heart failure? [2] c) What investigations you would want to perform? [2] d) What are the nonpharmacological and pharmacological managements? [4]" },
  { id: "pyq-2023-october-pi-05", session: "October 2023", year: 2023, paper: "I", number: 5, marks: 10, kind: "differentiate", question: "A 45-year-old male daily wage labourer has presented to you with recurrent episodes of breathlessness, cough and sputum production. He has given history of smoking since he was 15 years old, till recently he had been smoking 1 pack per day: a) How do you differentiate between bronchial asthma and COPD? [2] b) Write the differences on physical examination and chest X-ray, between obstructive and restrictive lung disease. [3] c) What are the complications of COPD? [2] d) Write briefly the management of COPD. [3]" },
  { id: "pyq-2023-october-pi-06", session: "October 2023", year: 2023, paper: "I", number: 6, marks: 10, kind: "long", question: "Miss Renuka had eaten prawn fry brought from outside. Suddenly she started feeling itching all over body. She developed urticarial rashes. Her PR- 122, BP- 80/45mmHg and SpO2- 90%: a) What is the condition? How will you assess the patient? [3] b) What are the causes of her condition? [1] c) How will you manage her? [4] d) What advice will you give her to prevent it? [2]" },
  { id: "pyq-2023-october-pi-07", session: "October 2023", year: 2023, paper: "I", number: 7, marks: 10, kind: "long", question: "A 74-year-old woman presents for her annual physical examination and notes increasing fatigue over the past 3 months. Her history is notable for longstanding systolic hypertension. A physical examination now demonstrates a blood pressure of 120/70 mmHg and an irregular pulse of approximately 120 bpm at rest. The patient’s body mass index is 22. An electrocardiogram confirms atrial fibrillation with a ventricular response of 120 bpm and ECG suggestive of left ventricular hypertrophy. An echocardiogram done a year earlier to evaluate left ventricular hypertrophy was notable only for mild, global left ventricular dysfunction with a left ventricular ejection fraction of 40% and mild mitral regurgitation. The patient’s chronic medical regimen includes lisinopril 20 mg, metoprolol XL 25 mg and 75 mg aspirin daily. A repeat echocardiogram performed in the office demonstrates an ejection fraction of 20% with global hypokinesis. a) What medications should be chosen to control the rate acutely? [2] b) What further work up is required for new onset AF? [2] c) Should one restore sinus rhythm or choose a strategy of rate control? [2] d) What are the anticoagulation requirements for this patient? [2] e) If the decision is made to maintain sinus rhythm after the cardioversion, what are the best medical or procedural options? [2]" },
  { id: "pyq-2023-october-pi-08", session: "October 2023", year: 2023, paper: "I", number: 8, marks: 10, kind: "enumerate", question: "A 29-year-old male has come with history of painless ulcer for the past 2 weeks over the penis. On examination, there is a single nontender indurated ulcer on the penis. Inguinal lymph nodes are enlarged: 2024 May paper 1 a) List the conditions which can cause genital ulcers. [2] b) What serological tests should be done? [2] c) How will you manage this patient? [2] 2 months later, he presents with urethral discharge. d) What organisms cause urethral discharge? [2] e) How will you manage him in this visit? [2]" },
  { id: "pyq-2023-october-pi-09", session: "October 2023", year: 2023, paper: "I", number: 9, marks: 10, kind: "enumerate", question: "A 30-year-old male presented to you with complaints of groin itching, which you diagnosed as fungal infection and you wanted to rule out diabetes and the GRBS- 297mg%: a) How do you confirm the diagnosis of diabetes mellitus? [1] b) What is the pathophysiology in type 1 and type 2 diabetes? [2] c) How do you manage an overweight recently diagnosed diabetic? [3] d) List two indications to start insulin in a diabetic? [2] e) How do you treat hypoglycemia in adults and neonate in a hospital setting? [2]" },
  { id: "pyq-2023-october-pi-10", session: "October 2023", year: 2023, paper: "I", number: 10, marks: 10, kind: "long", question: "A 28-year-old returned from Chennai when he presented with high grade fever, with chills and rigors: a) What are the differential diagnosis of fever with chills and rigors? [2] b) What is severe complicated malaria? [3] c) Write briefly about management of acute uncomplicated malaria and severe falciparum malaria. [3] d) Mention drug schedule for Chemoprophylaxis in chloroquine sensitive and resistant areas. [2] 2024 May paper 1" },
  { id: "pyq-2024-october-pi-01", session: "October 2024", year: 2024, paper: "I", number: 1, marks: 10, kind: "long", question: "A 40-year-old gentleman Mr. X presents to the family physician for routine check-up. On examination, his blood pressure was found to be 180/100 mmHg. He is reporting headache in the evenings for the past 1 month. He smokes 20 cigarettes per day for past 20 years. He consumes alcohol 180 ml per day for the past 5 years. His own brother had heart attack and angioplasty at the age of 40 years and he is worried whether he needs to take medications to prevent heart attack. a) What are the precautions you will take to avoid error in the measurement of blood pressure in your clinic? [1] b) How will you manage Mr. X? [4] c) Mention any three important anti-hypertensive drug classes recommended for Mr. X and mention their side effects. [3] d) What is hypertensive urgency and hypertensive emergency? [2]" },
  { id: "pyq-2024-october-pi-02", session: "October 2024", year: 2024, paper: "I", number: 2, marks: 10, kind: "long", question: "A 35-year-old male presents with complaints of vomiting blood for the past 2 days. On examination, he is pale with pulse rate of 110/minute and blood pressure of 90/50 mmHg. a) What is the immediate management recommended? [4] b) What are the possible differential diagnosis causing blood vomiting? [1] c) What are the types of blood and blood products available for transfusion? [2] d) What are the reactions caused by blood transfusion and how will you manage the transfusion reaction? [3]" },
  { id: "pyq-2024-october-pi-03", session: "October 2024", year: 2024, paper: "I", number: 3, marks: 10, kind: "enumerate", question: "A 20-year-old male, a college dropout, presents to the casualty with alleged history of taking a large number of Tab. Paracetamol less than an hour ago with the intention of deliberate self-harm. He is conscious and oriented with normal vitals. a) Mention the principles in the immediate management a patient with any drug overdose. [4] b) How will you manage this person in the hospital and after discharge? [6]" },
  { id: "pyq-2024-october-pi-04", session: "October 2024", year: 2024, paper: "I", number: 4, marks: 10, kind: "long", question: "A 40 year old obese lady with diabetes on your follow-up has presented with high grade fever and chills associated with vomiting and loin pain on right loin for past 1 day. On examination, she is febrile, toxic, dehydrated and has right renal angle tenderness. Her investigations showed urine WBC - 250 cells/cumm. a) How will you manage her in the first two days? [5] b) If the urine culture shows E.coli significant growth > 105 colonies grown, resistant to Cephalosporin and Penicillin group antibiotic, what is the preferred antibiotic of choice and justify your choice. [3] c) How will you manage this lady if this condition is recurring again? [2]" },
  { id: "pyq-2024-october-pi-05", session: "October 2024", year: 2024, paper: "I", number: 5, marks: 10, kind: "long", question: "A 20-year-old lady, a college student, presents with the complains of multiple painful papules with central blackish keratotic material and surrounding erythema, present in her face, neck, chest and upper back. These lesions started two months back and recently some lesions are painful. She is very much worried and disturbed. a) What is the probable diagnosis? [2] b) What is the etiology and pathogenesis of this condition? [3] c) How will you manage this skin lesions? [3] d) What is the prognosis and when will you refer this lady to the specialist? [2]" },
  { id: "pyq-2024-october-pi-06", session: "October 2024", year: 2024, paper: "I", number: 6, marks: 10, kind: "long", question: "A 45-year-old gentleman, a known case of hypertension on Tab. Amlodipine 10 mg once daily has come for follow-up. He is on regular medications and his blood pressure is 160/90 mm Hg. His BMI is 29 kg/ m2. His annual blood check-up shows Total Cholesterol - 280 mg/dl, Triglycerides - 155 mg/dl, HDL - 33 mg/dl and LDL cholesterol - 182 mg/dl. HbA1c - 7.8 %. His creatinine is 0.9 mg% and his urinary microalbumin excretion is 900 mg in 24 hours. a) Describe the pharmacological and non-pharmacological management needed for this patient. [5] b) Describe briefly the different oral anti-diabetic medications available – classification, mechanism of action and their side effects. [5]" },
  { id: "pyq-2024-october-pi-07", session: "October 2024", year: 2024, paper: "I", number: 7, marks: 10, kind: "long", question: "A 65-year-old gentleman on treatment for hypertension with tab. Hydrochlorothiazide 25 mg once daily, presents to the casualty with altered sensorium. There was no h/o fever / vomiting / diarrhea. The blood work-up showed Random Blood sugar of 210 mg, Creatinine of 0.9 mg and Serum Sodium of 115 mEq/L and Potassium of 4 mEq/L a) What is the likely cause for his altered sensorium? [2] b) How will you manage this patient? [4] c) How will you prevent this happening in the future? [2] d) What are the indications for referral to the specialist? [2] 2025 June paper 1" },
  { id: "pyq-2024-october-pi-08", session: "October 2024", year: 2024, paper: "I", number: 8, marks: 10, kind: "long", question: "A 45-year-old businessman comes to see you in the OPD with complaints of increasing abdominal distension. He consumes alcohol 180 to 360 ml daily for the past 10 years. On examination, you demonstrate fluid in the abdomen. a) What are the causes for ascites? [2] b) What are the other clinical features you will look for in this patient? [2] c) How will you further evaluate this person with ascites? [2] d) What are the complications of ascites? [2] e) How will you manage and follow up this person? [2]" },
  { id: "pyq-2024-october-pi-09", session: "October 2024", year: 2024, paper: "I", number: 9, marks: 10, kind: "long", question: "A group of 4 people presented with multiple episodes of loose stools and vomiting after having food in a fast food restaurant. After assessing them, you decide to admit to correct dehydration and for further evaluation. a) What are the different causes of gastroenteritis? [2] b) What are the clinical features you would look for in these people? [2] c) How will you further evaluate and manage? [4] d) What are the complications of severe AGE and when will you refer? [2]" },
  { id: "pyq-2024-october-pi-10", session: "October 2024", year: 2024, paper: "I", number: 10, marks: 10, kind: "long", question: "A 45-year-old man is on treatment for Parkinsonism and has come to see you for follow up. a) What is the aetiology for Parkinsonism? [2] b) What are the clinical features in Parkinsonism? [2] c) What are the differential diagnoses? [2] d) How will you treat and when would you refer? [4] 2025 June paper 1" },
  { id: "pyq-2022-june-pii-01", session: "June 2022", year: 2022, paper: "II", number: 1, marks: 10, kind: "define-classify", question: "A-78-year old lady with right sided hemiplegia is being discharged from hospital. Relatives are taking her to her home at a remote village. She is bedridden and is on indwelling catheter and Ryle’s tube feeding: a) What are the problems that you can anticipate in this patient? [2] b) What advice will you give to prevent bed sores in this patient? [3] c) How will you classify bedsores? [3] d) Family physician’s role in managing bed sores. [2]" },
  { id: "pyq-2022-june-pii-02", session: "June 2022", year: 2022, paper: "II", number: 2, marks: 10, kind: "long", question: "A 40 year old lady came with dilated and tortuous veins over lower portion of her left leg. Discuss the following: a) Anatomy of venous system of lower limb. [3] b) Clinical features of varicose vein. [3] c) Prevention and management of varicose vein. [4]" },
  { id: "pyq-2022-june-pii-03", session: "June 2022", year: 2022, paper: "II", number: 3, marks: 0, kind: "long", question: "Describe the anatomy, clinical features and management of plantar fasciitis. How can plantar fasciitis be prevented? [(3+3)+4]" },
  { id: "pyq-2022-june-pii-04", session: "June 2022", year: 2022, paper: "II", number: 4, marks: 10, kind: "long", question: "What is the pathogenesis of osteo-arthritis (OA)? What are the common joints involved, their symptoms, clinical features of osteo-arthritis? Outline the relevant investigations and management of OA. [2+4+4]" },
  { id: "pyq-2022-june-pii-05", session: "June 2022", year: 2022, paper: "II", number: 5, marks: 10, kind: "long", question: "A 10-year-old girl presented with purulent right ear discharge for last 3 days. She had similar complaints in the past on the same side. Describe in detail about clinical features, examination findings, investigations, treatment and complications of this condition. [2+2+2+2+2]" },
  { id: "pyq-2022-june-pii-06", session: "June 2022", year: 2022, paper: "II", number: 6, marks: 10, kind: "long", question: "Describe briefly the clinical anatomy, indications, contra-indications and complications of ankle block. How will you do the procedure? [8+2]" },
  { id: "pyq-2022-june-pii-07", session: "June 2022", year: 2022, paper: "II", number: 7, marks: 0, kind: "long", question: "Describe the possible ophthalmic complications of diabetes. Explain about stages of diabetic retinopathy and its management options available to the ophthalmologist. [5+(3+2)]" },
  { id: "pyq-2022-june-pii-08", session: "June 2022", year: 2022, paper: "II", number: 8, marks: 6, kind: "enumerate", question: "A 70 years old female, diabetic, strict vegetarian who is a mother of 5 children presented with history of dribbling of urine: a) Mention the types of urinary incontinence. [3] b) What are the possible aetiological factors in the case scenario given above? [3]" },
  { id: "pyq-2022-december-pii-09", session: "December 2022", year: 2022, paper: "II", number: 9, marks: 10, kind: "long", question: "A 30 years old male presented with severe epigastric pain since one day. His PR-110 bpm, BP-100/60 mm hg, RR-25/min. Write 4 diagnostic possibilities you would consider in this patient. Describe in detail about clinical features, investigations and management of each. [4+6]" },
  { id: "pyq-2022-december-pii-10", session: "December 2022", year: 2022, paper: "II", number: 10, marks: 10, kind: "enumerate", question: "A 40 years old lady came with a 3 cm size lump in the left breast. Enumerate differential diagnosis and management of each. [4+6]" },
  { id: "pyq-2022-december-pii-01", session: "December 2022", year: 2022, paper: "II", number: 1, marks: 10, kind: "long", question: "A 23-year-old Mrs. Renuka is being posted for emergency section for failed induction. a) Explain the clinical anatomy for spinal anesthesia with a diagram. [3] b) Discuss the pharmacological features of Bupivacaine used for spinal anesthesia. [3] c) What are the indications, contraindications, and complications of spinal anesthesia? [4]" },
  { id: "pyq-2022-december-pii-02", session: "December 2022", year: 2022, paper: "II", number: 2, marks: 10, kind: "long", question: "A 35-year-old lady accidentally suffered burns over the upper thighs upto the knee joints on both sides and below the umbilicus on the anterior surface of the abdomen. a) How will you assess burns in an adult? [2] b) How will you monitor the patient for complications? [3] c) Discuss the burns management of this lady. [5]" },
  { id: "pyq-2022-december-pii-03", session: "December 2022", year: 2022, paper: "II", number: 3, marks: 10, kind: "long", question: "A 51-year-old female presents with palpable swelling in her left breast of 3 months duration. She is post-menopausal for three years. She has no medical comorbidities. Menarche was at 11 years of age. She has 2 children with her first pregnancy at 29 years of age. a) How will you investigate this patient? [2] b) What are the current recommendations for screening for breast cancer? [3] c) Discuss the possible risk factors associated with malignancy of breast. [2] d) Outline the long term management of this patient by you as her family doctor. [3]" },
  { id: "pyq-2022-december-pii-04", session: "December 2022", year: 2022, paper: "II", number: 4, marks: 10, kind: "long", question: "Mrs. Varalakshmi had a fall in the bathroom and is unable to move her right leg and not able to bear weight. She has tenderness over the right leg anterior aspect. a) Describe the principles in management of fractures with a special mention about fracture of the lower limbs. [6] b) What are the early and late complications? [4]" },
  { id: "pyq-2022-december-pii-05", session: "December 2022", year: 2022, paper: "II", number: 5, marks: 10, kind: "long", question: "Mrs. Satya aged 40 years, presented to outpatient department with history of tiredness and fatigue, she gives history of heavy menstrual bleeding for 5 days, and on examination she is pale. a) What are the indications of blood transfusion? [2] b) What are the risks and complications of blood transfusion? [3] c) What tests will you do on the donor blood before transfusion? [2] d) What measures will you take before, during and after the transfusion in the ward? [3]" },
  { id: "pyq-2022-december-pii-06", session: "December 2022", year: 2022, paper: "II", number: 6, marks: 10, kind: "long", question: "A 18-year-old married lady, presents with pain in the right side of the abdomen for the past one day. On examination, she has tenderness in the right iliac fossa. a) What is your differential diagnosis? [3] b) What relevant history and examination will you perform? [3] c) How will you manage this condition if the patient is in shock? [4]" },
  { id: "pyq-2022-december-pii-07", session: "December 2022", year: 2022, paper: "II", number: 7, marks: 10, kind: "long", question: "A 15-year-old Sridhar presented to your OPD with history of profuse right ear discharge for 6 weeks? a) What is your diagnosis? What are the salient features? [2] b) What are the risk factors? Mention four common pathogens causing this condition? [3] c) What are the complications of this condition? [3] d) How will you manage this condition? [2]" },
  { id: "pyq-2022-december-pii-08", session: "December 2022", year: 2022, paper: "II", number: 8, marks: 10, kind: "enumerate", question: "A 35-year-old Devi, an agricultural worker, mother of two children, has come to the out- patient clinic with history of pain and discharge from Right eye associated with blurring of vision since she returned from the field. The right eye is red, and the cornea has haziness. a) List any THREE possible differential diagnosis. [3] b) How will you manage Mrs. Devi, if she refuses referral to eye doctor in the next town, as she need to take care of the two children? [7]" },
  { id: "pyq-2023-april-pii-01", session: "April 2023", year: 2023, paper: "II", number: 1, marks: 10, kind: "long", question: "A 56-year-old postman comes with pain in the legs for the last 3 years. Pain occurs in both the thighs and legs after walking for 15 min. It is relieved by rest. Since last two months, he has pain when he walks a short distance. He has been smoking about 6 to 8 cigarettes per day for the past 20 years. He also hurt his right leg over the lateral aspect few weeks ago and the wound is not healing: a) What is the probable diagnosis and differential diagnosis? [1] b) What clinical features would you look for? [2] c) How will you investigate this patient? [2] d) What treatment will you offer for the condition as well as the ulcer? [2] e) How will you help him to stop smoking? [3]" },
  { id: "pyq-2023-april-pii-02", session: "April 2023", year: 2023, paper: "II", number: 2, marks: 10, kind: "enumerate", question: "A 66-year-old lady presented with painful swelling of the lower eyelid near the bridge of the nose: a) Enumerate the differential diagnosis. [3] b) Discuss the management. [7]" },
  { id: "pyq-2023-april-pii-03", session: "April 2023", year: 2023, paper: "II", number: 3, marks: 10, kind: "long", question: "You are called to see a lady who was injured by a stove burst: a) What first aid will you provide? [2] b) How will you assess the severity of different injuries that the patient may suffer? [5] c) How will you manage this patient after discharge from the hospital? [3]" },
  { id: "pyq-2023-april-pii-04", session: "April 2023", year: 2023, paper: "II", number: 4, marks: 10, kind: "enumerate", question: "A 35-year-old labourer has come with low back which started suddenly after he lifted a heavy object: a) List the red flags in a patient presenting with low backache. [2] b) Discuss the history and clinical features of lumbosacral intervertebral disc prolapse, including a note on the dermatomes of the lower limb. [4] c) How will you assess if a patient with lumbosacral disc prolapse needs urgent referral? [2] d) Outline conservative management of lumbosacral disc prolapse. [2]" },
  { id: "pyq-2023-april-pii-05", session: "April 2023", year: 2023, paper: "II", number: 5, marks: 10, kind: "long", question: "A 14-year-old old boy presents with fever and sore throat: a) Write the differential diagnosis. [5] b) Discuss rational use of antibiotics for treating patients with sore throat. [5]" },
  { id: "pyq-2023-april-pii-06", session: "April 2023", year: 2023, paper: "II", number: 6, marks: 10, kind: "long", question: "A 24-year-old lady presents with a swelling in the right breast. Swelling is freely mobile and on palpation of the left breast, the physician detects two small swellings. Her grandmother died of carcinoma of breast and her mother is being treated for the same. Patient is worried about her conditon: a) What is the probable diagnosis? [1] b) What investigations will you do? [2] c) When will you refer the patient to a surgeon? [2] d) She wants to undergo special investigations she read about in the internet to screen for cancer. What will you advise her? [2] e) She has a 1-year-old child and wanted to discuss about contraception. What would you advise her? [3]" },
  { id: "pyq-2023-april-pii-07", session: "April 2023", year: 2023, paper: "II", number: 7, marks: 10, kind: "long", question: "A 48-year-old farmer who has been a diabetic for the last 15 years and on oral anti- diabetic drugs and insulin presents with an ulcer on the plantar aspect of the left foot: a) Describe physical examination findings that can help you in the assessment and management of the ulcer. [3] b) How wiill you manage the ulcer in family practice? [3] c) Discuss indications for referral to a surgeon. [2] d) Write a note on prevention of diabetic foot ulcer. [2]" },
  { id: "pyq-2023-april-pii-08", session: "April 2023", year: 2023, paper: "II", number: 8, marks: 10, kind: "long", question: "A 28-year-old married lady presents to a remote community health centre with fever and acute abdominal pain for the past 3 days. Pain is localised to the right illiac fossa. She has missed her periods by 5 days. On examination, she has tenderness in the right iliac fossa with no guarding or rigidity: a) What is the differential diagnosis for this presentation and the most probable cause? [2] b) How will you investigate her? [3] c) Can this patient be treated in a community health centre? If so, what is the treatment that you will recommend? [3] d) What are the indications for referral to a higher centre? [2]" },
  { id: "pyq-2023-april-pii-09", session: "April 2023", year: 2023, paper: "II", number: 9, marks: 0, kind: "long", question: "A labourer comes with severe pain in the right hand with a high fever. On examination, the right palm is swollen with tenderness over the mid palmar area:" },
  { id: "pyq-2023-october-pii-10", session: "October 2023", year: 2023, paper: "II", number: 10, marks: 10, kind: "long", question: "A male patient who has sex with men comes with severe pain and bleeding form the anal region: a) What is the differential diagnosis? [3] b) What investigations will you order? Give the reasons for the same. [4] c) What treatment will you provide for infective causes for this presentation? [3]" },
  { id: "pyq-2023-october-pii-01", session: "October 2023", year: 2023, paper: "II", number: 1, marks: 10, kind: "long", question: "A 42-year-old man has been diagnosed with diabetes for the last 5 years. He has been coming to you for regular follow up: a) How will you perform his foot examination? [2] b) What advice will you give him with regards to foot care? [2] c) What are the complications of diabetic foot? [2] d) What are the other causes of non-healing leg ulcer? [2] e) What are the principles of management of diabetic ulcer? [2]" },
  { id: "pyq-2023-october-pii-02", session: "October 2023", year: 2023, paper: "II", number: 2, marks: 10, kind: "enumerate", question: "A 40-year-old presented with the complaint of feeling dizzy: a) What are the conditions that you will enteratin in a patient presenting with dizziness? [2] b) Mention the causes of vertigo. [2] c) Which are the medications that can cause dizziness? [2] d) When do you refer a patient with dizziness? [2] e) What test you perform for BPPV, how will you manage BPPV? [2]" },
  { id: "pyq-2023-october-pii-03", session: "October 2023", year: 2023, paper: "II", number: 3, marks: 10, kind: "short-note", question: "A 28-year-old female came for antenatal checkup, she was found to be Hbs Ag positive. Her husband was also checked and found to be HBsAg positive: a) Who are the groups of people at increased risk for transmission? [2] b) Which are the acute phase and chronic phase serological markers? [2] c) What will be the course of disease? [2] d) Write briefly on management of chronic Hepatitis B. [2] e) If her husband was tested negative, what advice you would have given? [2]" },
  { id: "pyq-2023-october-pii-04", session: "October 2023", year: 2023, paper: "II", number: 4, marks: 10, kind: "short-note", question: "A 32-year-old male presented to you with palpable swelling in the left groin which he noticed a few days ago, he has mild pain while walking or on lifting weight: a) What are the differential diagnosis? [2] b) What are the common causes of inguinal and scrotal swelling? [2] c) How will you evaluate a patient with groin swelling? [2] d) What are the red flags of inguino scrotal swelling? [2] e) Write briefly on inguinal hernia. [2]" },
  { id: "pyq-2023-october-pii-05", session: "October 2023", year: 2023, paper: "II", number: 5, marks: 10, kind: "long", question: "A 23-year-old female presented to you with redness of left eye, which she noticed this morning, she also mentioned there was a sticky discharge: a) What are the common causes of red eye in primary care? [2] b) Mention at least 4 systemic conditions that can cause red eye. [2] c) Mention at least 6 must know points in the history. [3] d) What are the red flags in history of a patient with red eye? [1] e) Mention 4 conditions of the eyelid with which patients present to primary care. [2]" },
  { id: "pyq-2023-october-pii-06", session: "October 2023", year: 2023, paper: "II", number: 6, marks: 10, kind: "long", question: "A 58-year-old female a poorly controlled diabetic presented to you with ulcer and foul smelling discharge from left foot 2nd toe. X-ray showed osteomyelitis changes of the phalanges and toe amputation is planned: a) Mention at least three regional anesthesia given, and local anesthetic agents used. [2] b) What are the complications of regional anesthesia and how do we manage them? [2] c) What sedatives are used in primary care? [2] d) What are the injectable anesthetics? [2] e) What analgesics are used while performing minor procedures? [2]" },
  { id: "pyq-2023-october-pii-07", session: "October 2023", year: 2023, paper: "II", number: 7, marks: 10, kind: "enumerate", question: "A 32-year-old female presented to you with hot sambhar spilt all over her as she was getting it down the stove: a) What are scalds? What is the characteristic of scalds? [2] b) What is the upper limit of percentage of burns you will treat in primary care? [2] c) List pathophysiological changes in any 2 of these organs - skin/kidney/immunity/hematological. [3] d) Estimation of burn size in adult-using Rule of 9, depict it in the diagram. [3]" },
  { id: "pyq-2023-october-pii-08", session: "October 2023", year: 2023, paper: "II", number: 8, marks: 0, kind: "long", question: "A 65-year-old man presents with history of tiredness, frequent stools and decreased sleep for the past 3 months. She is a known diabetic on Metformin 1gm BD. She also reports to" },
  { id: "pyq-2024-may-pii-09", session: "May 2024", year: 2024, paper: "II", number: 9, marks: 10, kind: "define-classify", question: "A 65-year-old male presented with recent history, nausea and loss of appetite and dark coloured stools, he was pale and his haemoglobin was 6.5gm%: a) What clinical diagnosis you would offer as the cause of his anemia? [2] b) What all points you will elicit in history to find out the possible causes of anemia? [2] c) How do you classify hypovolemic shock? [2] d) What medications can cause anaemia? [2] e) What are the indications of blood transfusion in anemia?[2]" },
  { id: "pyq-2024-may-pii-10", session: "May 2024", year: 2024, paper: "II", number: 10, marks: 10, kind: "long", question: "A 24-year-old female has comes to you with history of swelling and tenderness of right breast for 2 days. She has mild fever and she is feeding her 3-month-old baby: a) Mention and briefly write about at least 4 breast conditions a patient present to Family practitioner. [3] b) Write the various types of nipple discharges and give one condition for each. [3] c) Write in detail how will you manage her? [4]" },
  { id: "pyq-2024-may-pii-01", session: "May 2024", year: 2024, paper: "II", number: 1, marks: 10, kind: "long", question: "A 48 year old man working in a petrol pump, has a problem of recurrent leg ulceration on his right leg just above medial malleolus. It is associated with dull ache and vague discomfort and associated edema towards evening. On examination there is a 2×3 cm shallow ulcer with serous discharge and pigmentation of surrounding skin present. a) What is your most probable diagnosis for his leg ulcer? [1] b) What are the examination findings you will look for in this patient and how will you treat this condition? [4] c) Mention ANY SIX factors that affect wound healing that may lead to non-healing ulcers. [3] d) What advice will you give to prevent recurrence? [2]" },
  { id: "pyq-2024-may-pii-02", session: "May 2024", year: 2024, paper: "II", number: 2, marks: 10, kind: "long", question: "A 10-year-old boy was brought to you complaining of impaired hearing and sensation of blocked ear. His teacher was complaining of decreased academic performance. On examination impacted wax is present in both external auditory meatus. a) What are the modalities of treatment? [2] b) Explain the procedure, contraindication & complication of syringing. [4] c) Indications for referral. [2] d) Red flags in hearing loss. [2]" },
  { id: "pyq-2024-may-pii-03", session: "May 2024", year: 2024, paper: "II", number: 3, marks: 10, kind: "long", question: "A 40-year-old man has come to you with severe pain and swelling in the left index finger. After examination, you diagnose paronychia and advise drainage of the pus. You want to drain it without causing much pain. a) Describe the procedure of the drainage of the paronychia in this patient. [3] b) Discuss local anaesthetic agents used in general practice. [7]" },
  { id: "pyq-2024-may-pii-04", session: "May 2024", year: 2024, paper: "II", number: 4, marks: 10, kind: "long", question: "A 22-year-old college student has come to the family doctor with pain and swelling in the right testis since morning. He also has dysuria, fever and vomiting for 1 day. He gives no history of trauma. a) What is the most probable diagnosis and differential diagnosis in this patient? [3] b) How will you resolve the differential diagnosis? [3] c) Describe the management of the testicular pain in this patient. [4]" },
  { id: "pyq-2024-may-pii-05", session: "May 2024", year: 2024, paper: "II", number: 5, marks: 10, kind: "long", question: "Thirty-year-old female came with numbness of her right palm on waking up in the mornings for the last six months, and it is steadily worsening. She gave history of weight gain, day time sleepiness and constipation. Her BMI was 26 kg/m2 a) What would be the most probable clinical diagnosis for her symptoms? [2] b) Name the common entrapment neuropathies. What are their symptoms? [3] c) What are the predisposing causes of entrapment at wrist? [1] d) Discuss the management of this patient. [4]" },
  { id: "pyq-2024-may-pii-06", session: "May 2024", year: 2024, paper: "II", number: 6, marks: 10, kind: "long", question: "Thirty-year-old male, agricultural worker, came with pain, redness and photophobia in the right eye. a) Mention any three clinical possibilities for this problem and how will you diagnose each in family practice? [6] b) How will you manage this patient with red-eye in Family Practice? [2] c) Mention two indications for referral to the specialist. [2]" },
  { id: "pyq-2024-october-pii-07", session: "October 2024", year: 2024, paper: "II", number: 7, marks: 10, kind: "enumerate", question: "Fifty-year-old diabetic and hypertensive male came with severe pain in right shoulder for past one week. His shoulder abduction movement is restricted to 90 degree. There was no history of any obvious trauma. a) Mention the possible causes of shoulder pain. [3] b) Discuss clinical examinations and special clinical tests that will help in your diagnosis. [4] c) Management of shoulder pain in this patient [3]" },
  { id: "pyq-2024-october-pii-08", session: "October 2024", year: 2024, paper: "II", number: 8, marks: 10, kind: "long", question: "You are called for a house visit to see an 80-year-old lady who is bedridden following right sided hemiplegia for the past 8 years. Caregivers are worried about an ulcer they noticed recently over the sacral area. a) What are the Stages of Pressure Sore? [2] b) What parts of your body do bedsores affect? What are the complications of bedsores? [3] c) What are the nonsurgical and surgical treatment for bedsores? [3] d) How can you prevent bedsores? [2]" },
  { id: "pyq-2024-october-pii-09", session: "October 2024", year: 2024, paper: "II", number: 9, marks: 10, kind: "long", question: "An 82-year-old lady had a fall in bathroom. She has been brought to you with right lower limb externally rotated. Her vitals being stable. a) What is your provisional diagnosis and the plan for management? [3] b) The relatives prefer to take her to a traditional bone setter for further treatment. How will you counsel the relatives regarding the complications? [3] c) What would you do to minimize trauma fractures in post-menopausal women? [4]" },
  { id: "pyq-2024-october-pii-10", session: "October 2024", year: 2024, paper: "II", number: 10, marks: 10, kind: "long", question: "A 45-year-old female presented to you with a painless lump in the left breast upper outer quadrant for past one month. It is firm in consistency, 3 x 3 cm in size and not freely mobile. There is no local warmth or tenderness over the lump. a) What are the differential diagnoses? [2] b) How will you approach and investigate a breast lump in family medicine? [4] c) What are the cancer screening tests you offer to a female patient and from which age till which age? [4]" },
  { id: "pyq-2024-october-pii-01", session: "October 2024", year: 2024, paper: "II", number: 1, marks: 10, kind: "long", question: "A 50-year-old lady with type 2 diabetes mellitus is referred to you for control of diabetes. During screening, she was found to have diabetic retinopathy. a) What are the types of diabetic retinopathy? [2] b) How will you screen for diabetic retinopathy in family practice? [1] c) What are the treatment options available for each type of diabetic retinopathy? [4] d) What is the role of Family physician in preventing diabetic retinopathy? [3]" },
  { id: "pyq-2024-october-pii-02", session: "October 2024", year: 2024, paper: "II", number: 2, marks: 10, kind: "long", question: "A 15-year-old girl is brought by her parents with complaints of right ear foul smelling profuse discharge for the past two months. a) Define chronic suppurative otitis media. [2] b) What are the types of chronic suppurative otitis media and how will you make the differential diagnosis? [3] c) How will you manage this girl? [3] d) What are the complications you expect and what are the indications of referral to a specialist? [2]" },
  { id: "pyq-2024-october-pii-03", session: "October 2024", year: 2024, paper: "II", number: 3, marks: 10, kind: "enumerate", question: "A 65-year-old post-menopausal lady with a BMI of 19, has been brought to the community health center with history of fall with outstretched hand while lifting weight at home an hour ago. She has severe pain and swelling in the left wrist. On examination, there is severe tenderness in the left wrist associated with swelling and deformity. a) What are the components of Colle's fracture? [3] b) How will you treat Colle's fracture if you are posted in the community health center if referral to specialist is not possible? [4] c) How will you prevent fracture in this lady in the future? [3]" },
  { id: "pyq-2024-october-pii-04", session: "October 2024", year: 2024, paper: "II", number: 4, marks: 10, kind: "enumerate", question: "An 18-year-old girl has come with swelling in front of the neck for the past three months. a) List the differential diagnosis. How will you differentiate thyroid swelling from other swellings? [3] b) Mention any four features of thyrotoxicosis you will look for in this patient. [2] c) What are the initial investigations and management in family practice? [4] d) List any two indications for surgical treatment? [1]" },
  { id: "pyq-2024-october-pii-05", session: "October 2024", year: 2024, paper: "II", number: 5, marks: 10, kind: "long", question: "A 45-year-old man is awaiting for inguinal hernia surgery. He is on treatment for type 2 diabetes and hypertension. He is a smoker and consumes alcohol. He is referred by a surgeon to optimize him for hernia surgery planned under regional anesthesia. a) Describe briefly the components of Pre-Anesthesia Check-up. [5] b) How will you optimize this person before hernia surgery? [5]" },
  { id: "pyq-2024-october-pii-06", session: "October 2024", year: 2024, paper: "II", number: 6, marks: 10, kind: "long", question: "A 78-year-old man was brought to the casualty with complaints of altered sensorium since morning. He has no comorbidities; he had sustained a trivial head injury few weeks ago. His Computerized Tomography of the brain showed a large subdural hematoma with midline shift. a) What is Glasgow Coma Scale? How will it help you in managing a patient with head injury? [5] b) What are the initial management recommended to stabilize this elderly man before referral? [3] c) What are the definitive treatment modalities recommended for this person? [2]" },
  { id: "pyq-2025-june-pii-01", session: "June 2025", year: 2025, paper: "II", number: 1, marks: 10, kind: "long", question: "A 53-year-old lady has come for a follow-up of her diabetes and hypertension; you send her for an annual eye checkup. a) Classification of diabetic retinopathy with diagrams. [3] b) How will you prevent the progression? [3] c) What are the ocular effects of hypertension? [4]" },
  { id: "pyq-2025-june-pii-02", session: "June 2025", year: 2025, paper: "II", number: 2, marks: 10, kind: "long", question: "A 43-year-old businessman arrived after a long air travel; the next day, he came to your OPD with complaints of pain in the calf of his right leg associated with swelling. a) Initial assessment and differential diagnosis of the presentation. [2+2] b) Management of the above condition outlining the criteria for outpatient therapy. [4] c) Long-term management of this businessman. [2]" },
  { id: "pyq-2025-june-pii-03", session: "June 2025", year: 2025, paper: "II", number: 3, marks: 10, kind: "long", question: "a) Management of recurrent epistaxis in a 5-year-old child. [5] b) A 70-year-old man has come with nasal bleeding for the past 1 hour. His blood pressure is 200/120 mmHg. How will you manage him? [5]" },
  { id: "pyq-2025-june-pii-04", session: "June 2025", year: 2025, paper: "II", number: 4, marks: 10, kind: "long", question: "A 55-year-old farmer who is a diabetic has come to you with unilateral red eye associated with severe pain. a) What are the differential diagnosis of unilateral red eye? [2] b) What are the additional history and examination required? [3] c) How will you manage this condition if there is history of trauma with a stick in the agricultural field? [5]" },
  { id: "pyq-2025-june-pii-05", session: "June 2025", year: 2025, paper: "II", number: 5, marks: 10, kind: "chart-flow", question: "A 33-year-old woman presented to the OPD with a history of back pain that radiated to the lateral aspect of the leg for 2 days: a) What are your differential diagnoses? [3] b) Discuss an algorithmic approach to the above mentioned condition. [4] c) Indications for imaging in a person presenting with low back ache. [3]" },
  { id: "pyq-2025-june-pii-06", session: "June 2025", year: 2025, paper: "II", number: 6, marks: 10, kind: "long", question: "Discuss the spinal anesthesia under the following headings: a) Choice of spinal drugs and baricity of drugs. [3] b) What complications do you anticipate and how will you manage? [3] c) Management after giving spinal anesthesia – (Hemodynamic management, level of block, sedation during spinal). [4]" },
  { id: "pyq-2025-june-pii-07", session: "June 2025", year: 2025, paper: "II", number: 7, marks: 10, kind: "long", question: "A 75-year-old post-menopausal woman has presented with fracture of both bones right lower limb after a trivial fall while on a regular walk. a) How will you assess this woman? [3] b) How will you manage this woman? [4] c) How will you prevent fracture in future for this woman? [3]" },
  { id: "pyq-2025-june-pii-08", session: "June 2025", year: 2025, paper: "II", number: 8, marks: 10, kind: "long", question: "A 44-year-old laborer presented with fever, abdominal pain dull aching in the right upper quadrant for the past 4 days. You also elicited the history of loose stools for past two weeks. He gives history of unsafe alcohol consumption for the past 10 years. On examination, he is febrile and toxic with soft abdomen with tender hepatomegaly and intercostal tenderness in the right hypochondrium. a) What is the probable diagnosis and differentials? [2] b) What workup will you do? [3] c) What medical treatment you will start? [3] d) When will you refer for surgical management? [2]" },
  { id: "pyq-2025-june-pii-09", session: "June 2025", year: 2025, paper: "II", number: 9, marks: 10, kind: "long", question: "A 21-year-old college student presented to you with right iliac fossa pain and vomiting. The pain initially started from the umbilicus and shifted to right iliac fossa. a) What scoring system will you use for the above condition and how will you interpret the score? [4] b) How will you manage the above condition? [4] c) What are the indications for referral for surgery? [2]" },
  { id: "pyq-2025-june-pii-10", session: "June 2025", year: 2025, paper: "II", number: 10, marks: 10, kind: "long", question: "A 17-year-old girl presented to you with a swelling in front of her neck, which moves with deglutition. On examination, her pulse rate is 130 per minute and she has fine tremors. a) What relevant history will you elicit and what will you look for in the examination? [3] b) Describe the thyroid Image reporting and data scoring system. [3] c) Describe the management of this 17-year-old girl. [4]" },
  { id: "pyq-2022-june-piii-01", session: "June 2022", year: 2022, paper: "III", number: 1, marks: 10, kind: "long", question: "What is pre-conceptional counseling? How will you advice a couple married an year ago, now planning for pregnancy? [2+8]" },
  { id: "pyq-2022-june-piii-02", session: "June 2022", year: 2022, paper: "III", number: 2, marks: 10, kind: "long", question: "A 35-year old sexually active lady presents to you with vaginal discharge. a) Briefly describe the differential diagnosis with their clinical features. [5] b) WHO syndromic approach to sexually acquired infections. [5]" },
  { id: "pyq-2022-june-piii-03", session: "June 2022", year: 2022, paper: "III", number: 3, marks: 10, kind: "long", question: "A 22-year old primigravida presented to you with bilateral pedal edema. On examination, her BP was 150/90 mm Hg: a) How will you manage this patient? [5] b) What are the complications you expect in this patient? [5]" },
  { id: "pyq-2022-june-piii-04", session: "June 2022", year: 2022, paper: "III", number: 4, marks: 10, kind: "enumerate", question: "Enumerate prevention and screening for cervical cancer. [10]" },
  { id: "pyq-2022-june-piii-05", session: "June 2022", year: 2022, paper: "III", number: 5, marks: 10, kind: "long", question: "Define puerperium. What are the common problems of puerperium? [2+8]" },
  { id: "pyq-2022-june-piii-06", session: "June 2022", year: 2022, paper: "III", number: 6, marks: 10, kind: "long", question: "a) Define Severe Acute Malnutrition (SAM). [2] b) How will you manage a child with uncomplicated SAM? [3] c) What are the serious complications faced by children with SAM and how will you manage them? [5]" },
  { id: "pyq-2022-june-piii-07", session: "June 2022", year: 2022, paper: "III", number: 7, marks: 10, kind: "long", question: "What are the benefits of breast feeding? Mother of a one-month-old baby came to you with complaint of decreased breast milk. How can this issue be addressed? [5+5]" },
  { id: "pyq-2022-june-piii-08", session: "June 2022", year: 2022, paper: "III", number: 8, marks: 10, kind: "long", question: "Mother of a one-year-old girl child brought the child with history of fever, breathing difficulty and stridor of one day duration. a) Outline the differential diagnosis of stridor and fever in this baby. [5] b) Management of each of these conditions. [5]" },
  { id: "pyq-2022-june-piii-09", session: "June 2022", year: 2022, paper: "III", number: 9, marks: 10, kind: "long", question: "A one-year-old girl child was brought to you with history of convulsions. She had history of fever since one day: a) What are the differential diagnosis? [2] b) How will you manage? [4] c) How will you advice the parents regarding prevention and management of further episodes? [4]" },
  { id: "pyq-2022-june-piii-10", session: "June 2022", year: 2022, paper: "III", number: 10, marks: 4, kind: "long", question: "a) Describe the national immunisation schedule. [4]" },
  { id: "pyq-2022-december-piii-01", session: "December 2022", year: 2022, paper: "III", number: 1, marks: 10, kind: "enumerate", question: "Define low birth weight. Mention the causes of low birth weight. What are the various ways in which you can prevent low birth weight? [2+3+5]" },
  { id: "pyq-2022-december-piii-02", session: "December 2022", year: 2022, paper: "III", number: 2, marks: 10, kind: "short-note", question: "Baby born 17 hours ago, was found to be icteric on examination. Baby is feeding well: a) Explain the bilirubin metabolism. [3] b) Write briefly on pathophysiology of neonatal hyperbilirubinemia. [3] c) How will you manage this baby? [4]" },
  { id: "pyq-2022-december-piii-03", session: "December 2022", year: 2022, paper: "III", number: 3, marks: 10, kind: "long", question: "Mrs. Rajani, primigravida, 38 weeks of gestation, admitted in the labor room of secondary care setting. She was induced for high blood pressure. Her BP at admission was recorded to be 164/112, Urine Albumin ++: a) Define preeclampsia and severe preeclampsia. [4] b) Discuss the management of this patient. [6]" },
  { id: "pyq-2022-december-piii-04", session: "December 2022", year: 2022, paper: "III", number: 4, marks: 10, kind: "long", question: "A multigravida delivered half an hour back. She was found to have a heavy gush of vaginal bleed: a) Define PPH. [2] b) What are the risk factors for PPH? [3] c) How will you manage this patient? [5]" },
  { id: "pyq-2022-december-piii-05", session: "December 2022", year: 2022, paper: "III", number: 5, marks: 10, kind: "long", question: "Pregnancy is one of the risk factors for UTI: a) Explain why a pregnant lady is at risk for UTI. [4] b) How would you manage a pregnant lady with UTI at various stages of pregnancy? [6]" },
  { id: "pyq-2022-december-piii-06", session: "December 2022", year: 2022, paper: "III", number: 6, marks: 10, kind: "long", question: "45-year-old Mrs. Geetha presented to outpatient department with history of heavy menstrual bleed for past 3 months during her cycles, occasionally she gave history of intermenstrual bleeding also: a) What are the causes of abnormal uterine bleeding? [2] b) What other history will you take and examination will you perform in Mrs. Geetha? [2] c) How will you manage Abnormal uterine bleed (Investigation and treatment)? [4] d) When will you refer her to a specialist? [2]" },
  { id: "pyq-2022-december-piii-07", session: "December 2022", year: 2022, paper: "III", number: 7, marks: 0, kind: "long", question: "9-months-old baby of Esther has presented in the OPD with history of 5 episodes of loose stools, associated with vomiting for one day. The child is weighing 6 kg, with the birth weight" },
  { id: "pyq-2023-april-piii-08", session: "April 2023", year: 2023, paper: "III", number: 8, marks: 10, kind: "long", question: "a) The pathogenesis of Acute Rheumatic Fever. [2] b) The Criteria used for the diagnosis of Rheumatic Fever. [3] c) How will you treat a 13-year-old School going girl Lakshmi, who presented with Acute Rheumatic fever? [3] d) How will you prevent the recurrence of this conditon? [2]" },
  { id: "pyq-2023-april-piii-09", session: "April 2023", year: 2023, paper: "III", number: 9, marks: 10, kind: "long", question: "Mrs. Rubina G3P2L1IUD presented at 24 weeks of gestational age for follow up. Her Glucose tolerance test results were as follows: 106, 194 and 176mg% at fasting, 1 hour and 2 hours respectively. She gives history of having gestational diabetes toward the later part in previous pregnancy and was on medical nutrition therapy: a) What is a high risk pregnancy? [2] b) What other relevant history and risk factors you will explore? [3] c) How will you follow up and manage this lady? [5]" },
  { id: "pyq-2023-april-piii-10", session: "April 2023", year: 2023, paper: "III", number: 10, marks: 10, kind: "long", question: "A 5-year-old child was brought by his mother with cough, and mild fever for past 2 weeks. His weight is 13 kg (Birth wt-2.9kg). His father was treated for pulmonary TB 3 months back: a) Discuss diagnosis of TB in this child. [2] b) Discuss the treatment of pediatric TB as per National TB elimination program. [4] c) What measures could have prevented the child from being infected by his father? [2] d) What advice will you give to the anganwadi that the child is attendng? [2]" },
  { id: "pyq-2023-april-piii-01", session: "April 2023", year: 2023, paper: "III", number: 1, marks: 10, kind: "enumerate", question: "A lady who underwent Caesarean section recently comes to you with her husband for temporary contraception advice. a) List all the temporary methods of contraception that this couple can use. [3] b) Discuss the advantages and disadvantages. [3+2] c) What is your advice for the couple? [2]" },
  { id: "pyq-2023-april-piii-02", session: "April 2023", year: 2023, paper: "III", number: 2, marks: 10, kind: "long", question: "Mr. B, an HIV positive patient, with supressed viral load gets married. The wife knows his condition and the couple is practising safe sex. Mr. B gives a frantic call saying that the condom ruptured during intercourse. a) What advice will you provide to the couple? [5] b) After 2 years of marriage, they decide to conceive a child. What advice and precautions will you give? [5]" },
  { id: "pyq-2023-april-piii-03", session: "April 2023", year: 2023, paper: "III", number: 3, marks: 10, kind: "long", question: "A 54-year-old post menopausal lady comes with history of white discharge per vagina (WDPV). a) What is the differential diagnosis? [4] b) What investigations will help you to decide the cause of WDPV? [3] c) How can this be managed in a community health centre? [2] d) What are the indications for referral? [1]" },
  { id: "pyq-2023-april-piii-04", session: "April 2023", year: 2023, paper: "III", number: 4, marks: 10, kind: "long", question: "A 24-year-old primi gravida comes to you for antenatal check up in the 3rd month. a) What tests will you do? [2] b) What advice will you provide for good pregnancy outcome? [3] At 30th week, she presented with pedal odema and her BP is 140/90 mmHg. c) What is your likely diagnosis? [1] d) What investigations will you order? [2] e) What are the danger signs that you will elicit to refer the patient to an obstetrician? [2]" },
  { id: "pyq-2023-april-piii-05", session: "April 2023", year: 2023, paper: "III", number: 5, marks: 10, kind: "long", question: "A 60-year-old lady comes with a mass that protrudes from the vagina when she voids. She is also upset that she sometimes \"leaks urine\". a) What is the likely diagnosis? [1] b) Discuss the clinical examinaion to assess her. [2] c) How will you manage her in the family practice setting? [4] d) When will you refer the patient for surgery and how will you prepare the patient for surgery? [3]" },
  { id: "pyq-2023-april-piii-06", session: "April 2023", year: 2023, paper: "III", number: 6, marks: 10, kind: "long", question: "A 7-year-old child has been advised to undergo dental extraction. The patient has Tetralogy of Fallot. What advice will you give the parents and the dentist? [10]" },
  { id: "pyq-2023-april-piii-07", session: "April 2023", year: 2023, paper: "III", number: 7, marks: 2, kind: "long", question: "A 4-year-old-girl is brought to you by her parents as she has been crying continuously and rubbing her left ear. a) What are the likely causes? [2]" },
  { id: "pyq-2023-october-piii-08", session: "October 2023", year: 2023, paper: "III", number: 8, marks: 10, kind: "long", question: "An 8-year-old girl comes with history of passing high coloured urine and headache. 3 weeks ago she was treated for scabies. a) What is the likely diagnosis? [2] b) What laboratory tests will confirm the diagnosis? [3] c) What treatment can be given to manage her in a communtiy health centre? [3] d) When should the child be referred to a major centre? [2]" },
  { id: "pyq-2023-october-piii-09", session: "October 2023", year: 2023, paper: "III", number: 9, marks: 10, kind: "long", question: "A 2nd standard student is brought by his mother to the hospital with fever and running nose for the past 5 days. He has received all his immunisations from the local PHC. He has a vescicular rash all over the body for the past 2 days which first started on his chest and spread out . a) What is the likely diagnosis? [2] b) How will you manage this patient? [4] c) How will you prevent the infection from spreading in the community as well as in the family? [4]" },
  { id: "pyq-2023-october-piii-10", session: "October 2023", year: 2023, paper: "III", number: 10, marks: 10, kind: "long", question: "A 3-year-old boy had high grade fever and developed generalised seizures. He recovered rapidly and is otherwise well now. a) What is the likely diagnosis? What are the clinical features of this condition? [3] b) What treatment will you administer? [1] c) What is the controversy in the treatment of this condition? [1] d) What advice will you provide the parents for prevention of this conditon? [3] e) The parents are worried about the future of the child. What advice will you give its prognosis? [2]" },
  { id: "pyq-2023-october-piii-01", session: "October 2023", year: 2023, paper: "III", number: 1, marks: 10, kind: "long", question: "A 35-year-old female high school teacher, who is overweight, consults you at 12 weeks of gestation. Her both parents are diabetic: a) How will you proceed? [2] b) What all investigations you will advise throughout her ANC? [3] c) What are the recommended minimum number of visits for low-risk pregnancy and at what gestation age? [2] d) What all conditions will lead to high-risk pregnancy? [3]" },
  { id: "pyq-2023-october-piii-02", session: "October 2023", year: 2023, paper: "III", number: 2, marks: 10, kind: "long", question: "Mrs Sabina has brought her 5-month-old baby with complaints of mild nasal discharge, otherwise baby is well. So far baby has been on only breast feed. She asks you about initiation of solid food: a) What is weaning? [2] b) Why and when should you wean the babies? [3] c) How and what type of foods will you advise? [3] d) How much complementary feeds should be weaning foods to contribute along with breast milk up to 24 months of age? [2]" },
  { id: "pyq-2023-october-piii-03", session: "October 2023", year: 2023, paper: "III", number: 3, marks: 10, kind: "long", question: "A 52-year-old female has not had periods for past 24 months. She comes to you with hot flushes and vaginal dryness: a) What is menopause and perimenopause? [2] b) What are the various clinical problems a lady goes through during menopause? [2] c) Write about the management of at least 4 clinical problems during menopause. [3] d) What are the benefits and harms of Hormone Replacement Therapy? [3]" },
  { id: "pyq-2023-october-piii-04", session: "October 2023", year: 2023, paper: "III", number: 4, marks: 10, kind: "long", question: "A 11-month-old male baby has been brought with complaints of upper respiratory infection. His weight now is 6.3Kg. His Birth weight was 3.3Kg. a) What is the grade of PEM as per IAP? [2] b) What are the common social factors that might have contributed? [3] c) What are the indications of admission for a patient with PEM? [2] d) What food regime in the initial phase would you advise and how will be the increase in calorie and protein intake? [3]" },
  { id: "pyq-2023-october-piii-05", session: "October 2023", year: 2023, paper: "III", number: 5, marks: 10, kind: "define-classify", question: "A 22-year-old primigravida at 35+3 weeks of GA presented with PPROM, delivered a 2.2 kg baby boy. a) What are the factors which increase the risk of low birth weight? [2] b) How do you grade and classify low birth weight babies? [2] c) What are the complications of low birth weight and how do you manage those complications? [2] d) How do you manage low birth weight babies? [2] e) How do you prevent the occurance of low birth weight in babies? [2]" },
  { id: "pyq-2023-october-piii-06", session: "October 2023", year: 2023, paper: "III", number: 6, marks: 10, kind: "long", question: "A 32-year-old female, P2L2 sterilized, has presented to you with history of heavy menstrual bleed (HMBL) for past 5 days. Her earlier periods were regular and lasted for 3 days. She had similar episode in last cycle, but since she noticed relatively excess bleeding this month, she came to consult you. a) What is Abnormal Uterine Bleeding (AUB)? [2] b) What is the etiology of AUB according to FIGO Classification? [3] c) How will you manage AUB in adolescents, perimenopausal, nonpregnant reproductive age group, and in post-menopausal women? [5]" },
  { id: "pyq-2023-october-piii-07", session: "October 2023", year: 2023, paper: "III", number: 7, marks: 10, kind: "short-note", question: "A 28-year-old female presented to you with complaints of vaginal white discharge. Its curdy, yellowish and foul smelling: a) What are the causes of white discharge per vaginum? [2] b) What are the various types of discharge you see on vaginal examination? [3] c) How will you manage this patient? [2] d) Write briefly on the management of sexually transmitted infections. [3]" },
  { id: "pyq-2024-may-piii-01", session: "May 2024", year: 2024, paper: "III", number: 1, marks: 10, kind: "long", question: "A 32-year-old pregnant lady PRIMI gravida at 37+2 weeks of gestation presents to you with headache and pedal edema. On examination her BP is 160/90mm on two recordings. She has puffy face and her urine albumin is 2+. a) What is your diagnosis? [1] b) How do you evaluate and manage her pregnancy and delivery? [6] c) What are the maternal and fetal complications you anticipate? [3]" },
  { id: "pyq-2024-may-piii-02", session: "May 2024", year: 2024, paper: "III", number: 2, marks: 10, kind: "long", question: "A 21-year-old primigravida at 40+5 weeks of gestational age, with no risk factors, had regular antenatal checkup in your primary health centre. She is admitted and induced with misoprostol and was augmented with pitocin this morning. a) Draw a partogram with the following findings and Discuss the uses of Partogram in monitoring the labour in a Primary Health Centre. [6] At 6am: The cervix is 4cm dilated and < 0.5cm thickness, soft, station is \"-3\", artificial rupture of membranes was done, liquor was clear, she has mild tightening. The FHR and mother's vitals are stable, over a period of next 4 hrs pitocin drip was increased to reach contraction of 3/10 each lasting for 40-45 seconds, throughout the FHR and liquor was normal. At 10 am : Cervix is 6cm Liquor is clear FHR is in normal range Contraction 3/10 each lasting for 40 seconds b) When will you repeat the next Per-vaginal examination and What action would you take if cervical dilatation is 7cm and all other parameters are within normal range? [1+3]" },
  { id: "pyq-2024-may-piii-03", session: "May 2024", year: 2024, paper: "III", number: 3, marks: 10, kind: "long", question: "Two year child, weighing 7 kg, is brought to you with history of loose stools, fever and vomiting of two days duration. There was no blood in stools. On examination, the child is irritable and demanding for water. The eyes are sunken. The child is actively drinking when provided with water. a) What is your diagnosis? [1] b) How will you assess the dehydration level in this child? [2] c) How will you manage this diarrhoeal episode? [4] d) What is the nutritional management in this child? [3]" },
  { id: "pyq-2024-may-piii-04", session: "May 2024", year: 2024, paper: "III", number: 4, marks: 10, kind: "long", question: "a) Describe the developmental milestones to be attained by a 3 year old child. [4] b) What are the common causes of delay in developmental milestones of a 3-year-old child, who had reached all his milestones till 18 months of age. [3] c) What are the clinical features of a child with autism? [3]" },
  { id: "pyq-2024-may-piii-05", session: "May 2024", year: 2024, paper: "III", number: 5, marks: 10, kind: "long", question: "What are the components of breast milk for a mother of a term baby? Describe the advantages of breast feeding upto the two years of age? Write about baby friendly hospital initiative. [3+4+3]" },
  { id: "pyq-2024-may-piii-06", session: "May 2024", year: 2024, paper: "III", number: 6, marks: 10, kind: "short-note", question: "A 21-year-old primigravida of 11 week gestation presented to you with history of spotting per vaginum. On examination vitals are stable and cervical os is closed with mild spotting. a) Define Abortion. [1] b) How do you classify abortion? [2] c) What kind of abortion is described in the above patient and how will you manage her? [3] d) Write briefly on medical termination of pregnancy Act. [4]" },
  { id: "pyq-2024-may-piii-07", session: "May 2024", year: 2024, paper: "III", number: 7, marks: 10, kind: "long", question: "a) What is pre-conceptional counselling? [2] b) What are the goals of preconceptional counselling? [2] c) What are the benefits of preconceptional counselling? [3] d) How do you implement it in your practice? [3]" },
  { id: "pyq-2024-may-piii-08", session: "May 2024", year: 2024, paper: "III", number: 8, marks: 10, kind: "long", question: "What are the hormonal contraceptives available? Describe the mechanisms of action and their side effect profile. Write a brief note on emergency contraception. [4+3+3]" },
  { id: "pyq-2024-may-piii-09", session: "May 2024", year: 2024, paper: "III", number: 9, marks: 10, kind: "define-classify", question: "a) Mention five common causes of infant death under five years of age in India. [3] b) Which guideline was issued by the Indian government to decrease morbidity and mortality in under five's [2] c) Classify and manage a child with diarrhoea according to the guidelines. [5]" },
  { id: "pyq-2024-may-piii-10", session: "May 2024", year: 2024, paper: "III", number: 10, marks: 10, kind: "define-classify", question: "You are running an immunization clinic in your primary health centre. The mothers are very reluctant to come forward for immunization as they are afraid of the Adverse Event Following Immunization. a) What is the basic concept of Adverse Event Following Immunisation (AEFI)? [2] b) How do you classify AEFI? [2] c) How will you manage AEFI? [2] d) As a team leader how will you investigate an AEFI? [4]" },
  { id: "pyq-2024-october-piii-01", session: "October 2024", year: 2024, paper: "III", number: 1, marks: 10, kind: "long", question: "A recently married young lady has missed her periods. Her pregnancy is confirmed with urine pregnancy test. She is 8 weeks pregnant and has come to see you with complaints of incessant vomiting. She is dehydrated. a) What are the differential diagnosis for the vomiting. [2] b) How will you manage excessive vomiting in the first trimester of pregnancy? [4] c) What are the conditions that need to be ruled out in this patient with excessive vomiting in the first trimester of pregnancy? [2] d) What are the indications for admission and referral? [2]" },
  { id: "pyq-2024-october-piii-02", session: "October 2024", year: 2024, paper: "III", number: 2, marks: 10, kind: "chart-flow", question: "A 25-year-old lady, married for one year, has come to see you after she missed her regular periods; Her pregnancy was confirmed with urine pregnancy test and she was prescribed folic acid. Today, she reports two months amenorrhea and having bleeding PV since one hour ago. a) What are the causes of bleeding PV in the first trimester of pregnancy? [4] b) Draw an algorithm for management of bleeding PV in the first trimester of pregnancy. [6]" },
  { id: "pyq-2024-october-piii-03", session: "October 2024", year: 2024, paper: "III", number: 3, marks: 10, kind: "long", question: "A 25-year-old PRIMI at 40+4 weeks of GA is admitted for safe confinement. She is in the second stage of labour and she looks exhausted. You would like to cut short second stage of labour. a) What are the indications for cutting short of second stage of labour? [3] b) What are the instruments used to cut short the second stage of labour? [4] c) What are the complications anticipated and how will you manage them? [3]" },
  { id: "pyq-2024-october-piii-04", session: "October 2024", year: 2024, paper: "III", number: 4, marks: 10, kind: "enumerate", question: "A 30-year-old pregnant lady G5P4L4 at 32 weeks of pregnancy has come for routine antenatal visit to the community health center. Her hemoglobin is 8 gm%, a) List the factors contributing to the anemia in pregnancy. [2] b) How will you manage anemia in this pregnancy? [4] c) What are the precautions need to be taken during the delivery and puerperium? [4]" },
  { id: "pyq-2024-october-piii-05", session: "October 2024", year: 2024, paper: "III", number: 5, marks: 10, kind: "long", question: "A young couple married for 4 years and living together and anxious to conceive. They have come to the family physician for the infertility evaluation. a) Define primary infertility. [2] b) How will you evaluate a couple for infertility in primary care? [4] c) What are the simple treatment measures that can be tried in the family practice before we refer to the specialist? [4]" },
  { id: "pyq-2024-october-piii-06", session: "October 2024", year: 2024, paper: "III", number: 6, marks: 0, kind: "long", question: "You are taking care of new born babies in a community health center." },
  { id: "pyq-2025-june-piii-07", session: "June 2025", year: 2025, paper: "III", number: 7, marks: 10, kind: "long", question: "A 5-year-old child is brought to you with complaints of cold, cough and fever since 3 days. Child has poor feeding and lethargy. On examination, the Respiratory rate was 38 per minute. a) How will you assess a child according to IMNCI for pneumonia? [5] b) How will you manage this child? [5]" },
  { id: "pyq-2025-june-piii-08", session: "June 2025", year: 2025, paper: "III", number: 8, marks: 10, kind: "long", question: "A 3-year-old boy, weighing 12 kg, is brought to the OPD with complaints of recurrent loose stools since morning. Child is thirsty and demanding water. Eyes look sunken and skin turgor is lost. a) How will you assess for dehydration in this child? [5] b) According to IMNCI how will you manage the child? [5]" },
  { id: "pyq-2025-june-piii-09", session: "June 2025", year: 2025, paper: "III", number: 9, marks: 10, kind: "long", question: "A 15-year-old boy is brought to you by his mother complaining of poor scholastic performance. a) What are the problems of adolescence? [5] b) Role of family physician in improving adolescent health in the community. [5]" },
  { id: "pyq-2025-june-piii-10", session: "June 2025", year: 2025, paper: "III", number: 10, marks: 10, kind: "long", question: "Eleven year old child staying in a hostel is brought by the warden complaining of behavioral changes with poor scholastic performance which is of recent onset. On exploring further you suspect child sexual abuse. a) What is POCSO Act? [5] b) What is the role of family physician in this scenario of suspected child sex abuse? [5]" },
  { id: "pyq-2025-june-piii-01", session: "June 2025", year: 2025, paper: "III", number: 1, marks: 10, kind: "long", question: "A 2-year-old boy was brought by his mother with complaints of fever, headache associated with vomiting for past 2 days. He is drowsy since this morning. On examination, he is febrile (103°F), conscious, lethargic and there was neck stiffness. There was no weakness in the extremities. a) What are your diagnosis and differential diagnoses? [2] b) What are the common organisms which cause the above condition? How will you manage this child in family practice? [5] c) What are the complications during the treatment that would need referral to the higher center? [3]" },
  { id: "pyq-2025-june-piii-02", session: "June 2025", year: 2025, paper: "III", number: 2, marks: 10, kind: "long", question: "a) What are the temporary methods of contraception available for a 23-year-old lady who had delivered the first child two weeks ago? How will you counsel the woman with different methods of contraception? [5] b) Relevance of Medical Termination of Pregnancy Act for the Family Physicians. [5]" },
  { id: "pyq-2025-june-piii-03", session: "June 2025", year: 2025, paper: "III", number: 3, marks: 10, kind: "long", question: "A newborn baby of a diabetic mother was being observed in the nursery. The nurse noticed lip-smacking movements in the baby and informed you. a) What are the common causes and classification of neonatal seizures? [5] b) How will you evaluate and manage neonatal seizures? [5]" },
  { id: "pyq-2025-june-piii-04", session: "June 2025", year: 2025, paper: "III", number: 4, marks: 10, kind: "define-classify", question: "A 23-year-old G3P1L1 SB1 at 36 weeks of gestational age with previous spontaneous preterm birth at 34 weeks with previous small for gestational age has come for ANC follow- up. a) What are the risk factors for preterm birth? [3] b) Which are the factors classify a pregnancy as a high-risk pregnancy? [3] c) What are the routine investigations and recommended visits included in antenatal care in a low-risk and high-risk pregnancy? [4]" },
  { id: "pyq-2025-june-piii-05", session: "June 2025", year: 2025, paper: "III", number: 5, marks: 10, kind: "long", question: "An 8-year-old child was brought with complaints of periorbital swelling noticed by the mother in the early mornings for past one week. The urine routine showed Albumin 4+ and no WBC or RBC. a) How will you evaluate this child? [3] b) How will you diagnose and manage Nephrotic syndrome? [5] c) What are the indications for referral to the specialist? [2]" },
  { id: "pyq-2025-june-piii-06", session: "June 2025", year: 2025, paper: "III", number: 6, marks: 10, kind: "long", question: "A 23-year-old primigravida at 24 weeks of gestation has come for antenatal care. You find her to be pale, and her Hb is 7.5 gm%; she is not able to tolerate oral iron supplements: a) How will you administer parenteral iron therapy–dose, dilution, duration and frequency? [3] b) What are the complications of anemia in pregnancy and in labor? [3] c) How will you manage the labor in a woman with anemia complicating pregnancy? [4]" },
  { id: "pyq-2022-june-piv-01", session: "June 2022", year: 2022, paper: "IV", number: 1, marks: 10, kind: "long", question: "What is meant by health and well-being? What all are essential for healthy living? How will you measure the quality of life? What are the social determinants of health? [2+2+2+4]" },
  { id: "pyq-2022-june-piv-02", session: "June 2022", year: 2022, paper: "IV", number: 2, marks: 10, kind: "long", question: "You have diagnosed 15 cases of Dengue fever infection in your area. How will you investigate and control this epidemic? [5+5]" },
  { id: "pyq-2022-june-piv-03", session: "June 2022", year: 2022, paper: "IV", number: 3, marks: 10, kind: "long", question: "A 50 year old man presented to you with a non-healing ulcer on his right foot. How will you assess him according to three stage assessment model? [10]" },
  { id: "pyq-2022-june-piv-04", session: "June 2022", year: 2022, paper: "IV", number: 4, marks: 10, kind: "long", question: "What is disaster cycle? How will you prepare the people in your CHC area for an anticipated flood? What is disaster mitigation? [2+6+2]" },
  { id: "pyq-2022-june-piv-05", session: "June 2022", year: 2022, paper: "IV", number: 5, marks: 10, kind: "enumerate", question: "What is the difference between 'referral of a patient' to a specialist and 'consultation by a specialist' when you send your patients for a second opinion? What are the legal implication for family practitioner when he sends a patient for consultation or referral? Discuss the referral system available in the public health institutions in our country. [3+2+5]" },
  { id: "pyq-2022-june-piv-06", session: "June 2022", year: 2022, paper: "IV", number: 6, marks: 10, kind: "long", question: "Discuss the various types of pneumococal vaccines that are available for immunisation in our country. Discuss the indications for this vaccine in adults. What is the schedule of the vaccination in children? [4+3+3]" },
  { id: "pyq-2022-june-piv-07", session: "June 2022", year: 2022, paper: "IV", number: 7, marks: 10, kind: "long", question: "What are the aims and objectives of Revised National TB Control Programme of India (elimination program 2020)? How does this programme help to achieve elimination of TB from India? With regard to HIV infection, what are the recommendations by the program? [3+5+2]" },
  { id: "pyq-2022-june-piv-08", session: "June 2022", year: 2022, paper: "IV", number: 8, marks: 10, kind: "long", question: "Define urban health. What are the major health issues seen in urban areas of India? How does National Urban Health Mission of India address these issues? [1+4+5]" },
  { id: "pyq-2022-june-piv-09", session: "June 2022", year: 2022, paper: "IV", number: 9, marks: 10, kind: "long", question: "Discuss briefly regarding problems of adolescence. What are the government schemes for adolescents? [6+4]" },
  { id: "pyq-2022-june-piv-10", session: "June 2022", year: 2022, paper: "IV", number: 10, marks: 10, kind: "long", question: "A 48 year old man came to see you to get advice regarding a trip to USA for 3 months. He is diabetic on insulin and OHA, and is having bronchial asthma controlled with inhalers. He is under your follow up. What immunisation will you advice? What medical documents will you provide for the patient? He wants to carry his medications for the trip. What advice will you provide? [3+3+4]" },
  { id: "pyq-2022-december-piv-01", session: "December 2022", year: 2022, paper: "IV", number: 1, marks: 10, kind: "long", question: "There has been a cholera outbreak in the locality where you practice. You have been asked by the local administration to investigate this. How will you proceed to ascertain the existing situation of outbreak? Briefly describe the study design, objective, methodology and associated factors. [4+6]" },
  { id: "pyq-2022-december-piv-02", session: "December 2022", year: 2022, paper: "IV", number: 2, marks: 10, kind: "long", question: "A family practitioner wants to establish a relationship between arreca nut chewing and oral cancer: a) What tests of association must he apply to identify the association? [5] b) How will confidence interval help to interpret the results? [5]" },
  { id: "pyq-2022-december-piv-03", session: "December 2022", year: 2022, paper: "IV", number: 3, marks: 10, kind: "long", question: "Infant mortality rate: a) Define infant mortality rate. [2] b) What are the determinants of infant mortality in India? [3] c) How will you prevent infant mortality in your community? [5]" },
  { id: "pyq-2022-december-piv-04", session: "December 2022", year: 2022, paper: "IV", number: 4, marks: 10, kind: "long", question: "a) Discuss the criteria for screening. [5] b) Describe the different methods of screening for cervical cancer. [5]" },
  { id: "pyq-2022-december-piv-05", session: "December 2022", year: 2022, paper: "IV", number: 5, marks: 10, kind: "long", question: "Discuss the importance of: a) Air pollution on health of the individual. [5] b) Biomedical waste seggregation in family practice. [5]" },
  { id: "pyq-2022-december-piv-06", session: "December 2022", year: 2022, paper: "IV", number: 6, marks: 10, kind: "short-note", question: "Discuss the principles of Family medicine. Write briefly on three stage assessment. [6+4]" },
  { id: "pyq-2022-december-piv-07", session: "December 2022", year: 2022, paper: "IV", number: 7, marks: 10, kind: "long", question: "a) The beneficiaries and benefits of Ayushman Bharat yojana. [5] b) Discuss Janani suraksha yogana (JSY) of the Government. [5]" },
  { id: "pyq-2022-december-piv-08", session: "December 2022", year: 2022, paper: "IV", number: 8, marks: 10, kind: "long", question: "The cesarean section rate in your hospital is 25%: a) How will you conduct an audit of the caserean sections being conduced in your hospital? [4] b) What are the principles of evidence based medicine that will help you to identify good practices? [4] c) How will you remedy the situation in your hospital? [2]" },
  { id: "pyq-2022-december-piv-09", session: "December 2022", year: 2022, paper: "IV", number: 9, marks: 10, kind: "long", question: "a) Various methods of temporary contraception. [5] b) Emergency contraception. [5]" },
  { id: "pyq-2022-december-piv-10", session: "December 2022", year: 2022, paper: "IV", number: 10, marks: 10, kind: "long", question: "a) Adult vaccination. [5] b) Steps in de-adiciton of alcohol. [5]" },
  { id: "pyq-2023-april-piv-01", session: "April 2023", year: 2023, paper: "IV", number: 1, marks: 10, kind: "long", question: "Discuss herd immunity and its place in the control of the Covid-19 pandemic. [10]" },
  { id: "pyq-2023-april-piv-02", session: "April 2023", year: 2023, paper: "IV", number: 2, marks: 10, kind: "long", question: "A famliy of four members went to a restaurant for dinner. 2 hours later, two of them developed vomiting and by 4 hours all of the members developed vomiting and had loose stools. a) What is the likely diagnosis? [1] b) How will you manage the family? [4] c) What is the role of the physician in informing the health authorities? [1] One of them had not passed any urine for the last 10 hours. d) How will you manage? [3] e) How could this complication be prevented? [1]" },
  { id: "pyq-2023-april-piv-03", session: "April 2023", year: 2023, paper: "IV", number: 3, marks: 10, kind: "long", question: "Discuss the advantages and disadvantages of telemedicine in family practice? [5+5]" },
  { id: "pyq-2023-april-piv-04", session: "April 2023", year: 2023, paper: "IV", number: 4, marks: 10, kind: "long", question: "As a part of family practice, a drug company wants to conduct a drug trial in your practice. a) What ethical issues have to be followed? [6] b) What are the various permissions that an individual doctor has to obtain before conducting the research? [2] c) Who will be ultimately responsible for adverse reactions financially, legally and ethically? [2]" },
  { id: "pyq-2023-april-piv-05", session: "April 2023", year: 2023, paper: "IV", number: 5, marks: 10, kind: "long", question: "a) What is Ayushman Bharat? [1] b) What are the advantages of Ayushman Bharat? [4] c) What are the disadvantages of Ayushman Bharat? [2] d) How can family medicine practioners be a part of this program? [3]" },
  { id: "pyq-2023-april-piv-06", session: "April 2023", year: 2023, paper: "IV", number: 6, marks: 10, kind: "long", question: "In a community survey, it is found that 41% of pre-school children are suffering from anaemia. a) What community measures can be undertaken to reduce the prevelance of anemia? [6] b) What individual measures can be taken to reduce the incidence of anaemia? [4]" },
  { id: "pyq-2023-april-piv-07", session: "April 2023", year: 2023, paper: "IV", number: 7, marks: 10, kind: "long", question: "Describe various statistical parameters used to assess the usefulness of a laboratory investigation. As a Family practitioner, how do these measures help you to choose a test for a particular condition? [5+5]" },
  { id: "pyq-2023-april-piv-08", session: "April 2023", year: 2023, paper: "IV", number: 8, marks: 2, kind: "long", question: "A 45-year-old man comes to you with a depigmented patch on the back. You examine and find that the patch is anaesthetic. a) What is your likely diagnosis? [2]" },
  { id: "pyq-2023-october-piv-09", session: "October 2023", year: 2023, paper: "IV", number: 9, marks: 10, kind: "long", question: "Discuss the problems faced by the elderly in the community. What measures can be taken to mitigate their conditon? [5+5]" },
  { id: "pyq-2023-october-piv-10", session: "October 2023", year: 2023, paper: "IV", number: 10, marks: 10, kind: "long", question: "Discuss the precautions in administering Covid-19 vaccines and possible side effects. [5+5]" },
  { id: "pyq-2023-october-piv-01", session: "October 2023", year: 2023, paper: "IV", number: 1, marks: 10, kind: "differentiate", question: "Mrs. Geetha presented to your OPD with two days’ history of cold, cough and throat pain. OPD sister recorded a BP of 160/110mmHg which she was unaware earlier. Re-examination by you also confirmed that she has hypertension. a) What is screening? Write the difference between screening and diagnostic tests. [2] b) What are the aims of screening? [2] c) What are the types of screening - write briefly about each? [2+2] d) What is the role of Family Physician in disease prevention? [2]" },
  { id: "pyq-2023-october-piv-02", session: "October 2023", year: 2023, paper: "IV", number: 2, marks: 10, kind: "short-note", question: "A 43-year-old presented with a hypopigmented patch over the face which she noticed for past 6 weeks. She also says she has mild decreased sensation over the area: a) How will you evaluate her? [2] b) How do you classify Hansen’s disease? [2] c) What treatment regimens are recommended? [3] d) Write briefly on Fernandez and Mitsuda reaction. [3]" },
  { id: "pyq-2023-october-piv-03", session: "October 2023", year: 2023, paper: "IV", number: 3, marks: 10, kind: "short-note", question: "A 34-year-old, mother of two children came to your OPD for generalised aches and pains, her weight is 96 Kg, and height is 154 cm. a) What will be her BMI? [1] b) How will you classify obesity as per WHO classification? [2] c) Write briefly on Epidemiology and etiopathogenesis of obesity. [3] d) What are the hazards of obesity? [2] e) How can you prevent obesity in the community - what level of prevention will it be? [2]" },
  { id: "pyq-2023-october-piv-04", session: "October 2023", year: 2023, paper: "IV", number: 4, marks: 10, kind: "enumerate", question: "You have been posted in a rural community health centre. You have noted that there were 32% of low-birth-weight infants among newborn children during the first quarter of 2021. You plan to determine the risk factors of low birth weight. a) What is the type of study design you would need to use if it has to be completed within a year of your posting and mention reasons? [3] b) State the objective of the study. [2] c) Mention the methodology of the study. [3] d) How will you analyse the data? [2]" },
  { id: "pyq-2023-october-piv-05", session: "October 2023", year: 2023, paper: "IV", number: 5, marks: 10, kind: "long", question: "Ms.Shivani, an engineering student, comes to you with history of unprotected sex the previous day: a) What are the various methods of temporary contraception? [3] b) What are the contraindications of oral contraceptive pills? [2] c) Write briefly about Emergency Contraception. [3] d) What are the other conditions for which we use OCP? [2]" },
  { id: "pyq-2023-october-piv-06", session: "October 2023", year: 2023, paper: "IV", number: 6, marks: 10, kind: "long", question: "You have been serving a certain geographical area, 10% of your daily OPD are diabetics, you want to evaluate how your care is for the diabetics: a) Describe an audit cycle and its components. [5] b) If you were to do an audit of diabetic control of the patients in your practice, what would you do? [5]" },
  { id: "pyq-2023-october-piv-07", session: "October 2023", year: 2023, paper: "IV", number: 7, marks: 10, kind: "short-note", question: "There has been an outbreak of diarrheal disease in a village near the PHC that you work: a) Discuss how you will investigate this outbreak. [5] b) Describe briefly on management of acute diarrhoea according to the IMNCI guidelines. [5]" },
  { id: "pyq-2023-october-piv-08", session: "October 2023", year: 2023, paper: "IV", number: 8, marks: 10, kind: "long", question: "A 28-year-old man has presented to your health centre with fever and body pain for past four days. There was no obvious focus of infection. Clinical examination reveals an erythematous rash over the chest, trunk and extremities. Pulse rate of 120 / minute. Blood pressure was 78/60 mmHg in right upper limb. There are patients with similar presentation for the past two weeks. His investigations revealed leukopenia and thrombocytopenia; WBC count of 2800/cumm and platelet count of 63,000/cumm. a) What are the possible differential diagnosis? How will you manage him? [5] You heard that there are similar fever patients in the locality from the community workers. b) How will you investigate and control this epidemic? [5]" },
  { id: "pyq-2024-may-piv-10", session: "May 2024", year: 2024, paper: "IV", number: 10, marks: 10, kind: "long", question: "A 35-year-old, a daily wage labourer presented with weight loss, cough and expectoration for past 3 weeks, with evening rise of fever: a) What are the objectives of Revised National Tuberculosis Control Programme? [2] b) How is the diagnosis, categorization of Tuberculosis done under RNTCP? [2+2] c) Write about the treatment regimens of Tuberculosis according to RNTCP? [4]" },
  { id: "pyq-2024-may-piv-01", session: "May 2024", year: 2024, paper: "IV", number: 1, marks: 10, kind: "long", question: "a) Define health. [2] b) What are the different levels of prevention that can be provided by Family Physicians? [4] c) Explain each level with an example. [4]" },
  { id: "pyq-2024-may-piv-02", session: "May 2024", year: 2024, paper: "IV", number: 2, marks: 10, kind: "long", question: "You have diagnosed 17 cases of malaria in a village of population of 1000 in the last one month. There was only one or two cases diagnosed in the previous months. a) Which are the vectors that transmit Dengue fever, Malarial fever and Chikungunya? [2] b) How will you investigate this outbreak? [4] c) How will you apply integrated vector control measures in the village? [4]" },
  { id: "pyq-2024-may-piv-03", session: "May 2024", year: 2024, paper: "IV", number: 3, marks: 10, kind: "long", question: "A 17-year-old boy in class 12 has been having headache for past 2 months almost every day which is progressively worsening. He has anorexia and lost weight from 52 to 45 kilos in one month. He is also reporting evening rise of temperature on and off for the past one month. His parents are professionals working abroad and he is studying in a hostel. His elder sister is studying in IIT Mumbai. He does not have any bad habits. He has depressed mood on and off. He says the life is not worth living anymore. His grand father had been treated for Pulmonary Tuberculosis when this boy was 5 years old. a) What are the various types of consultation models? [2] b) Explain the \"Three Stage Assessment Model of Consultation\". [3] c) Write the \"Three stage assessment\" of this boy and suggest a management plan for each problem. [5]" },
  { id: "pyq-2024-may-piv-04", session: "May 2024", year: 2024, paper: "IV", number: 4, marks: 10, kind: "long", question: "a) What are the various stages of disaster management cycle? [5] b) You are working as the Family Physician in a Primary Health Centre in a rural part of India. You are receiving an alert about a possibility of earthquake in your area in the next one hour. How will you prepare the villagers for an anticipated earthquake? [3] c) How will you mitigate the disaster caused by earthquake? [2]" },
  { id: "pyq-2024-may-piv-05", session: "May 2024", year: 2024, paper: "IV", number: 5, marks: 6, kind: "long", question: "a) What are the types of referrals. [3] b) Describe an ideal referral pathway in any health care system. [3]" },
  { id: "pyq-2024-october-piv-06", session: "October 2024", year: 2024, paper: "IV", number: 6, marks: 10, kind: "enumerate", question: "Write about adult vaccination schedule and list of adverse reactions you would warn the patients. [6+4]" },
  { id: "pyq-2024-october-piv-07", session: "October 2024", year: 2024, paper: "IV", number: 7, marks: 10, kind: "enumerate", question: "a) Mention the objectives of the recent National Tuberculosis Programme. [2] b) Write briefly about the following as per the National Tuberculosis Programme: i) Diagnosis of Tuberculosis. [2] ii) Categorization. [3] iii) Treatment of Tuberculosis. [3]" },
  { id: "pyq-2024-october-piv-08", session: "October 2024", year: 2024, paper: "IV", number: 8, marks: 10, kind: "long", question: "Describe the current delivery of primary healthcare in India. What are the challenges for the current system of primary healthcare in India? Give your suggestions to improve primary healthcare in India. [3+4+3]" },
  { id: "pyq-2024-october-piv-09", session: "October 2024", year: 2024, paper: "IV", number: 9, marks: 10, kind: "long", question: "a) What are the health problems of adolescent girls in India? [4] b) Briefly describe the government schemes for adolescent girls in India. [3] c) What are the interventions a family physician would do to improve the health of adolescent girls during the School Health visits? [3]" },
  { id: "pyq-2024-october-piv-10", session: "October 2024", year: 2024, paper: "IV", number: 10, marks: 10, kind: "long", question: "You conduct a school health screen for 10th graders and identify 30% of the students are overweight: a) What are the causes for more students being overweight in the past decade? [3] b) What are the future health risks for children with overweight and obesity? [3] c) What is your role in health promotion and prevention as family practitioner for this group of students? [4]" },
  { id: "pyq-2024-october-piv-01", session: "October 2024", year: 2024, paper: "IV", number: 1, marks: 10, kind: "long", question: "A 45-year-old man comes to see you for follow up his lymph node biopsy report. The biopsy is reported as Non-Hodgkin's lymphoma. Describe in detail the steps in breaking the bad news? [10]" },
  { id: "pyq-2024-october-piv-02", session: "October 2024", year: 2024, paper: "IV", number: 2, marks: 10, kind: "long", question: "A 40-year-old man, chronic smoker comes to see you seeking help to quit smoking. How will you help him in Smoking Cessation? [10]" },
  { id: "pyq-2024-october-piv-03", session: "October 2024", year: 2024, paper: "IV", number: 3, marks: 7, kind: "long", question: "A 12-year-old boy is brought by his mother with complaints of poor scholastic performance and behavioral problems. a) What are the causes of poor scholastic performance? [4] b) How will you evaluate this boy? [3]" },
  { id: "pyq-2025-june-piv-04", session: "June 2025", year: 2025, paper: "IV", number: 4, marks: 10, kind: "long", question: "Discuss \"Adult Immunization\" for a 50-year-old businessman who travels abroad frequently. [10]" },
  { id: "pyq-2025-june-piv-05", session: "June 2025", year: 2025, paper: "IV", number: 5, marks: 10, kind: "long", question: "A couple is planning to retire at 60 years of age. They have come to the family physician for a health check-up and seeking the advice on retirement planning. a) What are the common health problems which you anticipate at retirement age? [5] b) What are the health promotion recommended by the family physician for during retirement. [5]" },
  { id: "pyq-2025-june-piv-06", session: "June 2025", year: 2025, paper: "IV", number: 6, marks: 10, kind: "long", question: "a) Describe briefly about observational studies. [5] b) How do you calculate sample size in observational studies? [5]" },
  { id: "pyq-2025-june-piv-07", session: "June 2025", year: 2025, paper: "IV", number: 7, marks: 10, kind: "long", question: "a) What are the \"red flags\" and \"yellow flags\" in family practice? [5] b) How are they going to help you in patient management in the family practice? [5]" },
  { id: "pyq-2025-june-piv-08", session: "June 2025", year: 2025, paper: "IV", number: 8, marks: 10, kind: "long", question: "Describe in detail the steps of \"Calgary Cambridge Consultation Skills\". How will you apply these steps in Indian context with large number of patients coming to our outpatient clinic? [6+4]" },
  { id: "pyq-2025-june-piv-09", session: "June 2025", year: 2025, paper: "IV", number: 9, marks: 10, kind: "long", question: "You had unusually large number of patients in your clinic on a Saturday. There was delay in finishing the clinic as you had few sick patients as well. Meantime, you noticed that one of the patient got angry and fighting with nurses because of the delay. Describe the steps to address the \"angry patient\" in family practice? [10]" },
  { id: "pyq-2025-june-piv-10", session: "June 2025", year: 2025, paper: "IV", number: 10, marks: 10, kind: "long", question: "You are working as a medical officer in the community health center. You noticed increase in the number of patients with diarrheal illness in your area in the past one week. Few of the patients were admitted with hypotension and shock. There is no death reported so far. How will you manage this outbreak of diarrhea in your community? [10]" },
  { id: "pyq-2025-june-piv-01", session: "June 2025", year: 2025, paper: "IV", number: 1, marks: 10, kind: "long", question: "Mrs. I is a 35-year-old house-wife and mother of four girl children. She has come to your family practice for aches and pains. She has mild anemia and depression. For the past two years, she is going to mason work as her husband is not supporting the family. Her husband is going to laborer work but spends all the money in alcohol consumption. He consumes alcohol daily and he beat Mrs. I causing physical injuries. Her first child is 14 years old and a school drop out. First child is helping the mother in the household works and taking care of the other siblings. 11 year old and 7 year old children are going to school. Last child is 5 year old and still not started schooling. All the four children are malnourished, anemic and the elder daughter is depressed. a) Draw a family genogram. [2] b) How will you assess the \"functional status of the family\" using family APGAR? [4] c) How will you provide family therapy for this family? [4]" },
  { id: "pyq-2025-june-piv-02", session: "June 2025", year: 2025, paper: "IV", number: 2, marks: 10, kind: "long", question: "A 30-year-old Mr. A, is working as an IT professional and he is coming to you for health check-up. You find that he is smoking 10 cigarettes per day for the past 5 years. a) What are the stages of behavior change? [5] b) How will you help Mr. A to stop smoking by non-pharmacological and pharmacological methods? [5]" },
  { id: "pyq-2025-june-piv-03", session: "June 2025", year: 2025, paper: "IV", number: 3, marks: 10, kind: "long", question: "You are working as a medical officer in a community health centre. There are two secondary schools in your community. You have been requested to provide school health service from 6th standard to 11th standard children. a) What are the health problems of school children from 10 years to 16 years of age? [4] b) How will you implement \"school health service\" from 6th standard to 11th standard children. Describe briefly the components, implementation and evaluation of this program? [6]" },
];
